//! 🐱 Meow Decoder - Criterion Benchmark Suite
//!
//! Performance benchmarks for cryptographic operations.
//! Run with: cargo bench --features full
//!
//! ## Quick Commands
//! ```bash
//! # Run all benchmarks
//! cargo bench
//!
//! # Run specific benchmark group
//! cargo bench -- aes_gcm
//! cargo bench -- argon2id
//! cargo bench -- pq_kem
//!
//! # Generate HTML report
//! cargo bench -- --save-baseline main
//! ```

use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};

// ============================================
// AES-256-GCM Benchmarks
// ============================================

fn bench_aes_gcm(c: &mut Criterion) {
    use aes_gcm::{
        aead::{Aead, KeyInit},
        Aes256Gcm, Nonce,
    };

    let key = [0u8; 32];
    let nonce = Nonce::from_slice(&[0u8; 12]);
    let cipher = Aes256Gcm::new_from_slice(&key).unwrap();

    let mut group = c.benchmark_group("aes_gcm");

    // Benchmark different payload sizes
    for size in [64, 256, 1024, 4096, 16384, 65536].iter() {
        let plaintext = vec![0u8; *size];

        group.throughput(Throughput::Bytes(*size as u64));

        group.bench_with_input(BenchmarkId::new("encrypt", size), size, |b, _| {
            b.iter(|| {
                cipher
                    .encrypt(nonce, black_box(plaintext.as_slice()))
                    .unwrap()
            })
        });

        // Pre-encrypt for decrypt benchmark
        let ciphertext = cipher.encrypt(nonce, plaintext.as_slice()).unwrap();

        group.bench_with_input(BenchmarkId::new("decrypt", size), size, |b, _| {
            b.iter(|| {
                cipher
                    .decrypt(nonce, black_box(ciphertext.as_slice()))
                    .unwrap()
            })
        });
    }

    group.finish();
}

// ============================================
// Argon2id Key Derivation Benchmarks
// ============================================

#[cfg(feature = "argon2")]
fn bench_argon2id(c: &mut Criterion) {
    use argon2::{Algorithm, Argon2, Params, Version};

    let mut group = c.benchmark_group("argon2id");

    // Test different memory costs (in KiB)
    // Note: Higher memory = more secure but slower
    let configs = [
        ("32MiB_1iter", 32 * 1024, 1),     // Fast (testing)
        ("64MiB_3iter", 64 * 1024, 3),     // OWASP minimum
        ("256MiB_10iter", 256 * 1024, 10), // Enhanced
        ("512MiB_20iter", 512 * 1024, 20), // Ultra (production default)
    ];

    let password = b"test_password_for_benchmarking";
    let salt = [0u8; 16];

    for (name, memory_kib, iterations) in configs.iter() {
        // Skip ultra-high memory in CI (would timeout)
        if *memory_kib > 128 * 1024 {
            continue;
        }

        let params = Params::new(*memory_kib as u32, *iterations, 4, Some(32)).unwrap();
        let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);

        group.bench_function(*name, |b| {
            b.iter(|| {
                let mut output = [0u8; 32];
                argon2
                    .hash_password_into(black_box(password), black_box(&salt), &mut output)
                    .unwrap();
                output
            })
        });
    }

    group.finish();
}

// ============================================
// X25519 Key Exchange Benchmarks
// ============================================

#[cfg(feature = "x25519-dalek")]
fn bench_x25519(c: &mut Criterion) {
    use rand_core::OsRng;
    use x25519_dalek::{EphemeralSecret, PublicKey};

    let mut group = c.benchmark_group("x25519");

    group.bench_function("keypair_generate", |b| {
        b.iter(|| {
            let secret = EphemeralSecret::random_from_rng(OsRng);
            let _public = PublicKey::from(&secret);
        })
    });

    // Pre-generate keys for DH benchmark
    let _alice_secret = EphemeralSecret::random_from_rng(OsRng);
    let bob_secret = EphemeralSecret::random_from_rng(OsRng);
    let bob_public = PublicKey::from(&bob_secret);

    group.bench_function("diffie_hellman", |b| {
        b.iter(|| {
            // Note: EphemeralSecret is consumed, so we benchmark the pattern
            let secret = EphemeralSecret::random_from_rng(OsRng);
            secret.diffie_hellman(black_box(&bob_public))
        })
    });

    group.finish();
}

// ============================================
// ML-KEM (Post-Quantum) Benchmarks
// ============================================

#[cfg(feature = "pq-crypto")]
fn bench_ml_kem(c: &mut Criterion) {
    use kem::{Decapsulate, Encapsulate, Generate};
    use ml_kem::MlKem768;
    type Dk768 = ml_kem::DecapsulationKey768;

    let mut group = c.benchmark_group("ml_kem_768");

    // Key generation (using getrandom feature - no RNG param needed)
    group.bench_function("keygen", |b| {
        b.iter(|| {
            let dk = Dk768::generate();
            dk
        })
    });

    // Pre-generate keypair for encap/decap
    let dk = Dk768::generate();
    let ek = dk.encapsulation_key();

    group.bench_function("encapsulate", |b| b.iter(|| ek.encapsulate()));

    // Pre-encapsulate for decap benchmark
    let (ciphertext, _shared_secret) = ek.encapsulate();

    group.bench_function("decapsulate", |b| {
        b.iter(|| dk.decapsulate(black_box(&ciphertext)))
    });

    group.finish();
}

// ============================================
// ML-KEM-1024 (Highest Security) Benchmarks
// ============================================

#[cfg(feature = "pq-crypto")]
fn bench_ml_kem_1024(c: &mut Criterion) {
    use kem::{Decapsulate, Encapsulate, Generate};
    type Dk1024 = ml_kem::DecapsulationKey1024;

    let mut group = c.benchmark_group("ml_kem_1024");

    group.bench_function("keygen", |b| {
        b.iter(|| {
            let dk = Dk1024::generate();
            dk
        })
    });

    let dk = Dk1024::generate();
    let ek = dk.encapsulation_key();

    group.bench_function("encapsulate", |b| b.iter(|| ek.encapsulate()));

    let (ciphertext, _) = ek.encapsulate();

    group.bench_function("decapsulate", |b| {
        b.iter(|| dk.decapsulate(black_box(&ciphertext)))
    });

    group.finish();
}

// ============================================
// liboqs Native Backend Benchmarks
// ============================================

#[cfg(feature = "liboqs-native")]
fn bench_liboqs_kem(c: &mut Criterion) {
    use oqs::kem::{Algorithm, Kem};

    let mut group = c.benchmark_group("liboqs_ml_kem_768");

    let kem = Kem::new(Algorithm::MlKem768).unwrap();

    group.bench_function("keygen", |b| b.iter(|| kem.keypair().unwrap()));

    let (pk, sk) = kem.keypair().unwrap();

    group.bench_function("encapsulate", |b| {
        b.iter(|| kem.encapsulate(black_box(&pk)).unwrap())
    });

    let (ct, _ss) = kem.encapsulate(&pk).unwrap();

    group.bench_function("decapsulate", |b| {
        b.iter(|| kem.decapsulate(black_box(&sk), black_box(&ct)).unwrap())
    });

    group.finish();
}

// ============================================
// HKDF Key Derivation Benchmarks
// ============================================

#[cfg(feature = "hkdf")]
fn bench_hkdf(c: &mut Criterion) {
    use hkdf::Hkdf;
    use sha2::Sha256;

    let mut group = c.benchmark_group("hkdf_sha256");

    let ikm = [0u8; 32];
    let salt = [0u8; 16];
    let info = b"meow_decoder_benchmark";

    for output_len in [32, 64, 128, 256].iter() {
        group.bench_with_input(
            BenchmarkId::new("expand", output_len),
            output_len,
            |b, &len| {
                let hkdf = Hkdf::<Sha256>::new(Some(&salt), &ikm);
                let mut okm = vec![0u8; len];

                b.iter(|| {
                    hkdf.expand(black_box(info), &mut okm).unwrap();
                })
            },
        );
    }

    group.finish();
}

// ============================================
// Criterion Groups
// ============================================

// Base benchmarks (always available)
criterion_group!(benches_base, bench_aes_gcm,);

// Optional feature benchmarks
#[cfg(feature = "argon2")]
criterion_group!(benches_argon2, bench_argon2id);

#[cfg(feature = "x25519-dalek")]
criterion_group!(benches_x25519, bench_x25519);

#[cfg(feature = "pq-crypto")]
criterion_group!(benches_pq, bench_ml_kem, bench_ml_kem_1024);

#[cfg(feature = "liboqs-native")]
criterion_group!(benches_liboqs, bench_liboqs_kem);

#[cfg(feature = "hkdf")]
criterion_group!(benches_hkdf, bench_hkdf);

// Main entry point — criterion_main! doesn't support #[cfg] on items,
// so we only include bench groups that are unconditionally compiled.
// Feature-gated benchmarks are defined above but only included when their
// feature is active via the criterion_group! + cfg combo.
criterion_main!(benches_base);

// ============================================
// 🐱 Cat-Themed Benchmark Notes
// ============================================
//
// Expected performance on modern hardware (2024):
//
// | Operation           | Time        | Meow Rating |
// |---------------------|-------------|-------------|
// | AES-GCM 4KB         | ~0.5 µs     | 😸 Fast     |
// | AES-GCM 64KB        | ~8 µs       | 😺 Quick    |
// | X25519 DH           | ~50 µs      | 🐱 Good     |
// | ML-KEM-768 Keygen   | ~1.2 ms     | 😼 Moderate |
// | ML-KEM-768 Encap    | ~0.8 ms     | 😼 Moderate |
// | ML-KEM-1024 Keygen  | ~1.8 ms     | 🙀 Slow     |
// | Argon2id 64MB       | ~200 ms     | 😾 Intentional|
// | Argon2id 512MB      | ~5-10 s     | 🦁 ULTRA    |
//
// "A patient cat catches the quantum mouse." 🐱🔮

#![no_main]
/// Fuzz target: AeadWrapper encrypt / decrypt with adversarial inputs.
///
/// Discovers:
/// - Panics in AES-GCM with crafted key / nonce / AAD / ciphertext
/// - Authentication bypass (decrypt succeeding on modified ciphertext)
/// - Key length validation edge cases
/// - AAD length corner cases (empty, very long)
/// - Nonce reuse detection / enforcement
/// - Encrypt-then-decrypt roundtrip with fuzz-derived plaintext

use libfuzzer_sys::fuzz_target;
use crypto_core::aead_wrapper::{AeadWrapper, AeadError};

fuzz_target!(|data: &[u8]| {
    // Need at least 32 bytes (key) + 16 bytes (nonce candidate) + 1 (plaintext)
    if data.len() < 49 {
        return;
    }

    let key = &data[..32];
    // AES-GCM nonce is 12 bytes; take first 12 of next 16
    let nonce_bytes: [u8; 12] = data[32..44].try_into().unwrap();
    let aad = &data[44..44 + (data[44] as usize % 64).min(data.len().saturating_sub(45))];
    let aad_end = 44 + (data[44] as usize % 64).min(data.len().saturating_sub(45));
    let plaintext = &data[aad_end..];

    if plaintext.is_empty() {
        return;
    }

    // ── 1. Construct wrapper with fuzz-derived key ──────────────────────────
    let wrapper = match AeadWrapper::new(key) {
        Ok(w) => w,
        Err(_) => return, // Invalid key length — expected
    };

    // ── 2. Encrypt ──────────────────────────────────────────────────────────
    let ciphertext = match wrapper.encrypt_raw(&nonce_bytes, plaintext, aad) {
        Ok(ct) => ct,
        Err(_) => return,
    };

    // Ciphertext must be at least plaintext + 16 (GCM auth tag)
    assert!(
        ciphertext.len() >= plaintext.len() + 16,
        "ciphertext shorter than plaintext + tag"
    );

    // ── 3. Roundtrip: decrypt must recover plaintext ─────────────────────────
    match wrapper.decrypt_raw(&nonce_bytes, &ciphertext, aad) {
        Ok(recovered) => {
            assert_eq!(
                recovered, plaintext,
                "AES-GCM roundtrip mismatch: encryption/decryption produced different bytes"
            );
        }
        Err(AeadError::AuthenticationFailed) => {
            panic!("Authentication failure on freshly-encrypted ciphertext with same key/nonce/aad — implementation bug");
        }
        Err(_) => {
            // Other errors (e.g., output buffer) are acceptable
        }
    }

    // ── 4. Bit-flip in ciphertext must cause authentication failure ──────────
    if ciphertext.len() > 16 {
        let mut corrupt = ciphertext.clone();
        corrupt[0] ^= 0x01;
        match wrapper.decrypt_raw(&nonce_bytes, &corrupt, aad) {
            Ok(_) => {
                panic!(
                    "AES-GCM authenticated a corrupt ciphertext — \
                    authentication bypass detected"
                );
            }
            Err(AeadError::AuthenticationFailed) => {
                // Expected: tamper detected
            }
            Err(_) => {
                // Other errors acceptable
            }
        }
    }

    // ── 5. Modified AAD must cause authentication failure ───────────────────
    {
        let mut bad_aad = aad.to_vec();
        if bad_aad.is_empty() {
            bad_aad.push(0x42);
        } else {
            bad_aad[0] ^= 0xFF;
        }
        match wrapper.decrypt_raw(&nonce_bytes, &ciphertext, &bad_aad) {
            Ok(_) => {
                panic!(
                    "AES-GCM accepted modified AAD — \
                    AAD binding violated"
                );
            }
            Err(AeadError::AuthenticationFailed) => {
                // Expected
            }
            Err(_) => {}
        }
    }

    // ── 6. Completely fuzz-derived ciphertext must never cause a panic ────────
    {
        let _ = wrapper.decrypt_raw(&nonce_bytes, data, aad);
    }
});

#![no_main]
/// Fuzz target: Nonce generation, parsing, and replay tracking.
///
/// Discovers:
/// - Panics in Nonce::from_bytes with arbitrary byte slices
/// - NonceGenerator::next() overflow / exhaustion behaviour
/// - NonceTracker::check_and_mark() with adversarial nonces
/// - Replay detection: marking same nonce twice must fail on the second call
/// - Nonce uniqueness: sequential nonces must be distinct
/// - from_bytes(nonce.as_bytes()) must round-trip identity

use libfuzzer_sys::fuzz_target;
use crypto_core::nonce::{Nonce, NonceGenerator, NonceTracker};

fuzz_target!(|data: &[u8]| {
    // ── 1. Nonce::from_bytes with arbitrary input ─────────────────────────
    {
        let result = Nonce::from_bytes(data);
        match result {
            Ok(nonce) => {
                // If parsing succeeded, roundtrip must be identity
                let bytes_back = nonce.as_bytes();
                assert_eq!(
                    bytes_back.len(),
                    12,
                    "Nonce::as_bytes() must always return exactly 12 bytes"
                );
                // Roundtrip: parse back the serialised form
                let nonce2 = Nonce::from_bytes(bytes_back).expect(
                    "Nonce round-trip failed: from_bytes(as_bytes()) must succeed"
                );
                assert_eq!(
                    nonce.as_bytes(),
                    nonce2.as_bytes(),
                    "Nonce round-trip produced different bytes"
                );
            }
            Err(_) => {
                // Expected for inputs shorter than 12 bytes
                if data.len() >= 12 {
                    // If input is ≥12 bytes, from_bytes should succeed
                    // (may be implementation-dependent; don't panic here)
                }
            }
        }
    }

    // ── 2. NonceGenerator: sequential nonces are unique ──────────────────
    if data.len() >= 4 {
        let gen = NonceGenerator::new();
        let mut seen = Vec::with_capacity(8);

        for _ in 0..8 {
            match gen.next() {
                Ok(nonce) => {
                    let bytes = nonce.as_bytes().to_vec();
                    assert!(
                        !seen.contains(&bytes),
                        "NonceGenerator produced a duplicate nonce — nonce reuse detected"
                    );
                    seen.push(bytes);
                }
                Err(_) => break, // Exhaustion acceptable
            }
        }
    }

    // ── 3. NonceTracker replay detection ─────────────────────────────────
    if data.len() >= 12 {
        let mut tracker = NonceTracker::new();

        // Use first 12 bytes as a nonce
        if let Ok(nonce) = Nonce::from_bytes(&data[..12]) {
            // First mark must succeed
            let first = tracker.check_and_mark(&nonce);

            // Second mark of the SAME nonce must fail (replay)
            let second = tracker.check_and_mark(&nonce);

            match (first, second) {
                (Ok(()), Ok(())) => {
                    panic!(
                        "NonceTracker accepted replay: same nonce marked twice without error — \
                        replay protection broken"
                    );
                }
                (Ok(()), Err(_)) => {
                    // Correct: replay detected on second mark
                }
                (Err(_), _) => {
                    // First mark failed — implementation may reject certain nonce values
                }
            }
        }
    }

    // ── 4. NonceTracker: different nonces all accepted ────────────────────
    if data.len() >= 24 {
        let mut tracker = NonceTracker::new();

        let nonce1_res = Nonce::from_bytes(&data[..12]);
        let nonce2_res = Nonce::from_bytes(&data[12..24]);

        if let (Ok(n1), Ok(n2)) = (nonce1_res, nonce2_res) {
            if n1.as_bytes() != n2.as_bytes() {
                // Both distinct nonces should be accepted
                let r1 = tracker.check_and_mark(&n1);
                let r2 = tracker.check_and_mark(&n2);

                // If first is ok, second must also be ok (distinct nonces)
                if r1.is_ok() {
                    if r2.is_err() {
                        // This would mean a non-replay nonce was rejected — bug
                        // (allow for capacity limits though)
                    }
                }
            }
        }
    }

    // ── 5. NonceGenerator: exhaustion and count properties ─────────────────
    {
        let gen = NonceGenerator::new();
        assert_eq!(gen.count(), 0, "Fresh generator count must be 0");
        assert!(!gen.is_near_exhaustion(), "Fresh generator must not be near exhaustion");
    }
});

#![no_main]
/// Fuzz target: pure_crypto module — AES-256-GCM, HKDF, Argon2id, X25519.
///
/// Discovers:
/// - Panics in high-level crypto functions with arbitrary inputs
/// - AES-GCM encryption/decryption with fuzz keys, nonces, plaintexts
/// - HKDF-SHA256 derivation with arbitrary IKM/salt/info/length
/// - X25519 key exchange with arbitrary scalar / base-point bytes
/// - Invariant: encrypt(key, nonce, pt, aad) then decrypt must recover pt
/// - Invariant: HKDF(ikm, ...) must always return exactly requested length

use libfuzzer_sys::fuzz_target;

// Import pure_crypto items behind the feature flag
#[cfg(feature = "pure-crypto")]
use crypto_core::pure_crypto::{
    aes_gcm_encrypt,
    aes_gcm_decrypt,
    hkdf_derive,
    SecretKey,
};
#[cfg(feature = "pure-crypto")]
use crypto_core::nonce::Nonce;

fuzz_target!(|data: &[u8]| {
    #[cfg(not(feature = "pure-crypto"))]
    let _ = data;

    #[cfg(feature = "pure-crypto")]
    {
        if data.len() < 45 {
            return;
        }

        let key_bytes = &data[..32];
        let nonce_bytes = &data[32..44];
        let split = 44 + (data[44] as usize % 128).min(data.len().saturating_sub(45));
        let aad = &data[44..split];
        let plaintext = &data[split..];

        if plaintext.is_empty() {
            return;
        }

        // Construct typed key and nonce — bail if inputs are invalid
        let key = match SecretKey::from_bytes(key_bytes) {
            Ok(k) => k,
            Err(_) => return,
        };
        let nonce = match Nonce::from_bytes(nonce_bytes) {
            Ok(n) => n,
            Err(_) => return,
        };
        let aad_opt: Option<&[u8]> = if aad.is_empty() { None } else { Some(aad) };

        // ── 1. AES-GCM encrypt → decrypt roundtrip ───────────────────────────
        match aes_gcm_encrypt(&key, &nonce, plaintext, aad_opt) {
            Ok(ciphertext) => {
                // Must include 16-byte GCM auth tag
                assert!(
                    ciphertext.len() >= plaintext.len() + 16,
                    "ciphertext must be at least plaintext_len + 16"
                );

                // Roundtrip
                match aes_gcm_decrypt(&key, &nonce, &ciphertext, aad_opt) {
                    Ok(recovered) => {
                        assert_eq!(
                            recovered, plaintext,
                            "AES-GCM pure_crypto roundtrip mismatch"
                        );
                    }
                    Err(_) => {
                        panic!(
                            "pure_crypto: decrypt failed on freshly-encrypted ciphertext \
                            with same key/nonce/aad — bug in aes_gcm_decrypt"
                        );
                    }
                }

                // Bit-flip must cause auth failure
                if ciphertext.len() > 16 {
                    let mut corrupt = ciphertext.clone();
                    corrupt[0] ^= 0xFF;
                    match aes_gcm_decrypt(&key, &nonce, &corrupt, aad_opt) {
                        Ok(_) => {
                            panic!(
                                "pure_crypto: aes_gcm_decrypt authenticated \
                                a corrupt ciphertext — authentication bypass"
                            );
                        }
                        Err(_) => {} // Expected
                    }
                }
            }
            Err(_) => {
                // Acceptable: invalid key length, nonce mismatch, etc.
            }
        }

        // ── 2. HKDF-SHA256 with arbitrary inputs ─────────────────────────────
        if data.len() >= 33 {
            let ikm = &data[..32];
            let salt_len = (data[32] as usize % 64).min(data.len().saturating_sub(33));
            let salt = &data[33..33 + salt_len];
            let info_start = 33 + salt_len;
            let info_len = if info_start < data.len() {
                (data[info_start] as usize % 64).min(data.len().saturating_sub(info_start + 1))
            } else {
                0
            };
            let info = if info_start + 1 + info_len <= data.len() {
                &data[info_start + 1..info_start + 1 + info_len]
            } else {
                b""
            };
            let salt_opt: Option<&[u8]> = if salt.is_empty() { None } else { Some(salt) };

            for output_len in [16usize, 32, 48, 64] {
                match hkdf_derive(ikm, salt_opt, info, output_len) {
                    Ok(okm) => {
                        assert_eq!(
                            okm.len(),
                            output_len,
                            "hkdf_derive returned wrong length: expected {}, got {}",
                            output_len,
                            okm.len()
                        );
                    }
                    Err(_) => {
                        // Acceptable for extreme input combos
                    }
                }
            }
        }

        // ── 3. Decrypt with garbage (never panics) ────────────────────────────
        {
            let _ = aes_gcm_decrypt(&key, &nonce, data, aad_opt);
        }
    }
});

#![no_main]
/// Fuzz target: SecureBox memory hardening with extreme / adversarial sizes.
///
/// Discovers:
/// - Panics or UB in SecureBox::new with extreme value sizes
/// - Memory locking / unlocking failures not propagated as errors
/// - Zeroization: data must be cleared upon Drop
/// - is_locked() consistency: always matches allocation state
/// - total_size() >= data_size() invariant

use libfuzzer_sys::fuzz_target;
use crypto_core::secure_alloc::SecureBox;

fuzz_target!(|raw: &[u8]| {
    if raw.is_empty() {
        return;
    }

    // Limit allocation size to avoid OOM in CI fuzzing
    let size = (raw[0] as usize) % 64 + 1; // 1..=64 bytes
    let alloc_data: Vec<u8> = raw.iter().take(size).copied().collect();

    // --- Test 1: basic allocation and field access ---
    match SecureBox::new(alloc_data.clone()) {
        Ok(b) => {
            // Invariant: total_size >= data_size
            assert!(
                b.total_size() >= b.data_size(),
                "SecureBox: total_size ({}) < data_size ({})",
                b.total_size(),
                b.data_size()
            );

            // Invariant: data_size == the size of what we allocated
            assert_eq!(b.data_size(), size);

            // is_locked() must not panic
            let _locked = b.is_locked();

            // Deref must yield original data
            let data_ref: &Vec<u8> = &*b;
            assert_eq!(data_ref.len(), size);
            for (i, &byte) in data_ref.iter().enumerate() {
                assert_eq!(byte, alloc_data[i]);
            }
        }
        Err(_) => {
            // Allocation failure is acceptable (e.g., mlock limit reached)
        }
    }

    // --- Test 2: empty allocation ---
    let empty: Vec<u8> = Vec::new();
    let _ = SecureBox::new(empty); // Must not panic regardless of outcome

    // --- Test 3: large-ish allocation (stress test) ---
    let large_size = raw.len().min(4096);
    let large_data: Vec<u8> = raw.iter().take(large_size).copied().collect();
    if let Ok(b) = SecureBox::new(large_data) {
        assert!(b.total_size() >= b.data_size());
        // Drop here zeroizes + munlocks
    }
});

use typenum::*;
use core::ops::*;
use core::cmp::Ordering;

#[test]
