    #[test]
    fn test_full_encrypt_then_mac_pipeline() {
        // Derive key from password
        let salt = Salt::from_bytes(&[0xAAu8; 16]).unwrap();
        let params = Argon2Params {
            memory_kib: 1024,
            time: 1,
            parallelism: 1,
