        let enc_key = hkdf_derive_key(&shared, Some(b"salt"), b"meow_enc_key").unwrap();

        let nonce = Nonce::from_bytes(&[0x42u8; 12]).unwrap();
        let ct = aes_gcm_encrypt(&enc_key, &nonce, b"x25519 test", Some(b"aad")).unwrap();
