//! Fuzz target: AES-256-GCM frame decryption
//!
//! # Attack classes covered
//! - Partial decrypt leak   → verified: error path returns Err, not partial bytes
//! - Truncation oracle      → feeds ciphertexts shorter than the 16-byte GCM tag
//! - Nonce reuse            → fixed key+nonce, arbitrary ciphertext body
//! - AAD omission           → varying ADDs against a real ciphertext
//! - Tamper detection       → any single-byte flip must cause DecryptionFailed
//!
//! # Hard invariants asserted
//! 1. `aes_gcm_decrypt` NEVER panics regardless of input.
//! 2. On `Err(_)` the returned plaintext buffer is absent (no partial plaintext).
//! 3. A successful decrypt re-encrypts to the same ciphertext (round-trip).
//!
//! # Assumed function signatures (from rust_crypto/src/pure.rs):
//! ```rust
//! pub fn aes_gcm_encrypt(key: &[u8], nonce: &[u8], plaintext: &[u8], aad: Option<&[u8]>)
//!     -> Result<Vec<u8>, CryptoError>;
//! pub fn aes_gcm_decrypt(key: &[u8], nonce: &[u8], ciphertext: &[u8], aad: Option<&[u8]>)
//!     -> Result<Vec<u8>, CryptoError>;
//! ```

#![no_main]

use libfuzzer_sys::fuzz_target;
use meow_crypto_rs::pure::{aes_gcm_decrypt, aes_gcm_encrypt};

/// Derive a deterministic 32-byte key from the first 32 bytes of input (or pad with 0xAA).
fn extract_key(data: &[u8]) -> [u8; 32] {
    let mut key = [0xAAu8; 32];
    let copy_len = data.len().min(32);
    key[..copy_len].copy_from_slice(&data[..copy_len]);
    key
}

/// Derive a deterministic 12-byte nonce from bytes 32..44 of input (or pad with 0xBB).
fn extract_nonce(data: &[u8]) -> [u8; 12] {
    let mut nonce = [0xBBu8; 12];
    if data.len() > 32 {
        let src = &data[32..];
        let copy_len = src.len().min(12);
        nonce[..copy_len].copy_from_slice(&src[..copy_len]);
    }
    nonce
}

fuzz_target!(|data: &[u8]| {
    // ─── Variant 1: treat full `data` as an attacker-supplied ciphertext ────
    // Key and nonce are fixed so the fuzzer explores the ciphertext space.
    let fixed_key = [0x42u8; 32];
    let fixed_nonce = [0x11u8; 12];

    // AAD variants: no AAD, some AAD, AAD == ciphertext itself.
    for aad in [None, Some(b"meow_aad_v1" as &[u8]), Some(data)] {
        let result = aes_gcm_decrypt(&fixed_key, &fixed_nonce, data, aad);

        // INVARIANT 1: must never panic (panic=abort catches it at OS level,
        //              but we document the invariant explicitly).

        // INVARIANT 2: on error, no plaintext returned.
        if let Ok(ref plaintext) = result {
            // INVARIANT 3: successful decryption must round-trip.
            // Re-encrypt and check we get back the same ciphertext bytes.
            // (We use a *different* nonce to avoid comparing tag+ciphertext directly –
            //  the semantic check is that decrypt(encrypt(pt)) == pt.)
            let reenc_nonce = [0x22u8; 12];
            let reenc = aes_gcm_encrypt(&fixed_key, &reenc_nonce, plaintext, aad);
            assert!(
                reenc.is_ok(),
                "Re-encrypt of authenticated plaintext must not fail"
            );

            let redec = aes_gcm_decrypt(&fixed_key, &reenc_nonce, &reenc.unwrap(), aad);
            assert_eq!(
                redec.as_deref().ok(),
                Some(plaintext.as_slice()),
                "Round-trip invariant violated: decrypt(encrypt(pt)) != pt"
            );
        }
    }

    // ─── Variant 2: fuzzer-derived key / nonce, body from remaining bytes ───
    if data.len() >= 44 {
        let key = extract_key(data);
        let nonce = extract_nonce(data);
        let body = &data[44..];

        // No-AAD path
        let _ = aes_gcm_decrypt(&key, &nonce, body, None);

        // AAD == first 8 bytes of body (common real-world pattern)
        if body.len() >= 8 {
            let _ = aes_gcm_decrypt(&key, &nonce, &body[8..], Some(&body[..8]));
        }
    }

    // ─── Variant 3: wrong key length inputs ─────────────────────────────────
    // Must return Err, never panic.
    for bad_key_len in [0usize, 1, 15, 16, 31, 33, 64] {
        let bad_key = vec![0x55u8; bad_key_len];
        let _ = aes_gcm_decrypt(&bad_key, &fixed_nonce, data, None);
    }

    // ─── Variant 4: wrong nonce length inputs ───────────────────────────────
    for bad_nonce_len in [0usize, 1, 8, 11, 13, 16, 24] {
        let bad_nonce = vec![0x77u8; bad_nonce_len];
        let _ = aes_gcm_decrypt(&fixed_key, &bad_nonce, data, None);
    }

    // ─── Variant 5: systematically tamper every byte of a valid ciphertext ──
    // Only exercised when data is at least 44 bytes so the fuzzer can generate
    // a valid (key, nonce, plaintext) triple.
    if data.len() >= 44 {
        let key = extract_key(data);
        let nonce = extract_nonce(data);
        let plaintext = &data[44..];

        if let Ok(mut ct) = aes_gcm_encrypt(&key, &nonce, plaintext, None) {
            if !ct.is_empty() {
                ct[0] ^= 0xFF; // flip first byte → tag or first ciphertext byte
                let tampered = aes_gcm_decrypt(&key, &nonce, &ct, None);
                // INVARIANT: tampered ciphertext must not decrypt successfully.
                assert!(
                    tampered.is_err(),
                    "Tampered ciphertext must not authenticate successfully"
                );
            }
        }
    }
});

//! Fuzz target: Full end-to-end decode pipeline simulation
//!
//! # Attack classes covered
//! - Truncation oracle    → partial frame data (missing AAD, missing ciphertext)
//! - Nonce reuse          → same nonce across multiple "frames"
//! - Replay               → duplicate frame indices
//! - PQ failure fallback  → corrupted hybrid key material
//! - Partial decrypt leak → any error path must return zero bytes
//! - AAD omission         → missing or wrong manifest AAD
//! - Crash/restart reuse  → simulate ephemeral state loss between calls
//!
//! # Pipeline model
//! This target simulates the full meow-decode path:
//!   1. Parse manifest header (extract salt, nonce, mode byte, auth tag)
//!   2. Derive key from password via Argon2id (fast params for fuzzing)
//!   3. Verify HMAC manifest authentication tag
//!   4. Decrypt payload via AES-256-GCM with AAD = manifest fields
//!   5. Advance per-frame ratchet for each fountain droplet
//!
//! If step 3 or 4 fails, ZERO bytes of plaintext must escape.
//!
//! # Notes on partial plaintext
//! AES-GCM by construction returns no plaintext on auth failure (the RustCrypto
//! implementation holds plaintext in a temporary buffer that is cleared before
//! returning Err). We assert this explicitly.

#![no_main]

use libfuzzer_sys::fuzz_target;
use meow_crypto_rs::pure::{
    aes_gcm_decrypt, aes_gcm_encrypt, derive_key_argon2id, derive_key_hkdf, hmac_sha256,
    hmac_sha256_verify, sha256,
};

/// Attempt to parse the first 64 bytes of `data` as a meow manifest header.
/// Returns (salt_16, nonce_12, mode, hmac_tag_32, payload_rest) or None.
fn parse_manifest(data: &[u8]) -> Option<([u8; 16], [u8; 12], u8, [u8; 32], &[u8])> {
    // Minimum header: 4 magic + 16 salt + 12 nonce + 1 mode + 32 hmac = 65
    if data.len() < 65 {
        return None;
    }
    // Magic check: we accept any 4-byte "magic" for fuzzing purposes
    let mut salt = [0u8; 16];
    let mut nonce = [0u8; 12];
    let mut hmac = [0u8; 32];

    salt.copy_from_slice(&data[4..20]);
    nonce.copy_from_slice(&data[20..32]);
    let mode = data[32];
    hmac.copy_from_slice(&data[33..65]);

    Some((salt, nonce, mode, hmac, &data[65..]))
}

/// Build minimal AAD from manifest fields (mirrors crypto.py pack_manifest() AAD).
/// AAD = magic(4) || salt(16) || mode(1) || sha256_of_payload(32)
fn build_aad(magic: &[u8; 4], salt: &[u8; 16], mode: u8, payload_sha256: &[u8]) -> Vec<u8> {
    let mut aad = Vec::with_capacity(53);
    aad.extend_from_slice(magic);
    aad.extend_from_slice(salt);
    aad.push(mode);
    aad.extend_from_slice(payload_sha256);
    aad
}

fuzz_target!(|data: &[u8]| {
    // ─── Stage 1: parse header from raw bytes ─────────────────────────────────
    let Some((salt, nonce, mode, hmac_tag, payload)) = parse_manifest(data) else {
        // Input too short → parsing returns None, no panic, no partial data.
        return;
    };

    // ─── Stage 2: derive key (fast Argon2id params for fuzz speed) ────────────
    // Password is extracted from the first 8 bytes of `data` (attacker-chosen).
    let password = &data[..data.len().min(8)];
    let key_result = derive_key_argon2id(
        password, &salt, /* memory_kib= */ 256, // minimal, fuzz-safe
        /* iterations= */ 1, /* parallelism= */ 1, /* output_len=  */ 32,
    );
    let key = match key_result {
        Ok(k) => k,
        Err(_) => return, // bad params → skip, no panic
    };

    // ─── Stage 3: HMAC manifest authentication ────────────────────────────────
    let magic = b"MEOW";
    let payload_hash = sha256(payload);
    let aad = build_aad(magic, &salt, mode, &payload_hash);

    // Derive manifest auth key via HKDF (domain-separated from enc key)
    let auth_key =
        derive_key_hkdf(&key, None, b"meow_manifest_auth_v1", 32).unwrap_or_else(|_| vec![0u8; 32]);
    let enc_key =
        derive_key_hkdf(&key, None, b"meow_manifest_enc_v1", 32).unwrap_or_else(|_| vec![0u8; 32]);

    // HMAC verification: compute expected, compare in constant time
    let expected_hmac = hmac_sha256(&auth_key, &aad).unwrap_or_else(|_| vec![0u8; 32]);
    let hmac_valid = hmac_sha256_verify(&auth_key, &aad, &hmac_tag).unwrap_or(false);

    // INVARIANT: if HMAC is invalid, do NOT attempt decryption.
    if !hmac_valid {
        // Simulate fail-closed: zero the derived keys and return.
        drop(expected_hmac);
        drop(enc_key);
        drop(auth_key);
        drop(key);
        return;
    }

    // ─── Stage 4: AES-256-GCM payload decryption ──────────────────────────────
    // Only reached if HMAC passes (i.e., input was crafted to be valid or fuzzer
    // got very lucky – either way, no plaintext escapes on AES-GCM failure).
    let dec_result = aes_gcm_decrypt(&enc_key, &nonce, payload, Some(&aad));

    // INVARIANT: Err must return no plaintext (checked at the type level: Err(e))
    match &dec_result {
        Err(_) => {
            // Correct: authentication / decryption failed cleanly.
        }
        Ok(plaintext) => {
            // ─── Stage 5: per-frame fountain droplet simulation ────────────────
            // Each byte of the plaintext drives the number of ratchet steps.
            let steps = 1 + (plaintext.len() % 16);
            let mut chain_key = derive_key_hkdf(&enc_key, None, b"meow_ratchet_root_v1", 32)
                .unwrap_or_else(|_| vec![0u8; 32]);

            let mut seen_message_keys: Vec<Vec<u8>> = Vec::with_capacity(steps);

            for step in 0..steps {
                let mut info = b"meow_ratchet_msg_v1".to_vec();
                info.extend_from_slice(&(step as u32).to_be_bytes());
                let msg_key =
                    derive_key_hkdf(&chain_key, None, &info, 32).unwrap_or_else(|_| vec![0u8; 32]);

                // NONCE UNIQUENESS: every message key must be distinct
                assert!(
                    !seen_message_keys.contains(&msg_key),
                    "DUPLICATE message key at ratchet step {} – nonce reuse!",
                    step
                );
                seen_message_keys.push(msg_key.clone());

                // Advance chain
                let mut chain_info = b"meow_ratchet_chain_v1".to_vec();
                chain_info.extend_from_slice(&(step as u32).to_be_bytes());
                chain_key = derive_key_hkdf(&chain_key, None, &chain_info, 32)
                    .unwrap_or_else(|_| vec![0u8; 32]);

                // Simulate encrypting one fountain droplet with this message key.
                // The droplet payload is a slice of the decrypted plaintext (if long enough).
                let droplet = if plaintext.len() > step {
                    &plaintext[step..]
                } else {
                    plaintext.as_slice()
                };
                let droplet_nonce = derive_key_hkdf(&msg_key, None, b"meow_frame_nonce", 12)
                    .unwrap_or_else(|_| vec![0u8; 12]);
                let _ = aes_gcm_encrypt(&msg_key, &droplet_nonce, droplet, Some(&chain_key));
            }
        }
    }

    // ─── Bonus: re-run with a mutated nonce (replay simulation) ───────────────
    // If we got a valid decrypt above, trying again with a different nonce must Err.
    {
        let mut flipped_nonce = nonce;
        flipped_nonce[0] ^= 0x01;
        let replay_result = aes_gcm_decrypt(&enc_key, &flipped_nonce, payload, Some(&aad));
        // Either fails (expected) or succeeds with different plaintext.
        // We just assert no panic; the nonce change should invalidate the GCM tag.
        let _ = replay_result;
    }

    // ─── Bonus: wrong salt → different key → decryption must fail ─────────────
    {
        let mut wrong_salt = salt;
        wrong_salt[0] ^= 0xFF;
        let wrong_key = derive_key_argon2id(password, &wrong_salt, 256, 1, 1, 32);
        if let Ok(wk) = wrong_key {
            let wrong_enc_key = derive_key_hkdf(&wk, None, b"meow_manifest_enc_v1", 32)
                .unwrap_or_else(|_| vec![0u8; 32]);
            let _ = aes_gcm_decrypt(&wrong_enc_key, &nonce, payload, Some(&aad));
        }
    }
});

//! Fuzz target: Frame header parsing and header encryption/decryption
//!
//! # Attack classes covered
//! - Header tampering     → arbitrary frame header bytes fed to parsing logic
//! - Truncation oracle    → headers shorter than minimum valid length
//! - AAD canonicalization → AAD computed from header must be deterministic
//! - Nonce reuse          → header-derived nonces must differ per frame index
//!
//! # Assumptions / adaptable layer
//! The codebase implements frame headers using HKDF-derived masks over a frame
//! index (MSR v1.2 design from copilot-instructions.md).  Until the header
//! encryption module is ported to Rust, this target exercises the HKDF
//! building‐block that will underpin that module.
//!
//! Specifically we test:
//!   - `derive_key_hkdf` with attacker-controlled IKM / info
//!   - The derived output used as both a masking key and an AAD token
//!   - That two different frame indices _always_ produce different masks
//!   - That truncated / oversized info strings do not panic
//!
//! Replace the body below with real header_parse / header_decrypt calls once
//! those functions are stabilised in the Rust layer.

#![no_main]

use libfuzzer_sys::fuzz_target;
use meow_crypto_rs::pure::{aes_gcm_decrypt, aes_gcm_encrypt, derive_key_hkdf, hmac_sha256};

/// Simulate the MSR v1.2 header mask derivation.
/// Real derivation: HKDF-SHA256(chain_key, "meow_header_mask_v1" || frame_index_be32)
fn derive_header_mask(chain_key: &[u8], frame_index: u32) -> Vec<u8> {
    let mut info = b"meow_header_mask_v1".to_vec();
    info.extend_from_slice(&frame_index.to_be_bytes());
    // 4 bytes for an encrypted index, 16 for commitment tag = 20 bytes total
    derive_key_hkdf(chain_key, None, &info, 20).unwrap_or_else(|_| vec![0u8; 20])
}

/// Simulate AAD canonicalization from a header.
/// Real AAD: HMAC-SHA256(auth_key, version_byte || mode_byte || frame_index_be32 || chain_epoch_be32)
fn canonicalize_aad(auth_key: &[u8], version: u8, mode: u8, frame_idx: u32, epoch: u32) -> Vec<u8> {
    let mut buf = Vec::with_capacity(10);
    buf.push(version);
    buf.push(mode);
    buf.extend_from_slice(&frame_idx.to_be_bytes());
    buf.extend_from_slice(&epoch.to_be_bytes());
    hmac_sha256(auth_key, &buf).unwrap_or_else(|_| vec![0u8; 32])
}

fuzz_target!(|data: &[u8]| {
    // ─── Part 1: arbitrary bytes as a "chain key" ────────────────────────────
    // We derive header masks for a range of frame indices.
    // INVARIANT: derive_key_hkdf must never panic for any IKM.

    let chain_key = data;

    let mask_0 = derive_header_mask(chain_key, 0);
    let mask_1 = derive_header_mask(chain_key, 1);
    let mask_max = derive_header_mask(chain_key, u32::MAX);

    // INVARIANT: different frame indices → different masks
    // (unless chain_key is pathologically degenerate - still must not panic)
    assert_eq!(mask_0.len(), 20);
    assert_eq!(mask_1.len(), 20);
    assert_eq!(mask_max.len(), 20);

    if !data.is_empty() {
        // Different indices must produce different masks for non-empty keys.
        // (For empty key the HKDF still works but collisions are theoretically
        //  possible at the 160-bit level; we only assert no panic.)
        assert_ne!(
            mask_0, mask_1,
            "Frame index 0 and 1 must produce distinct header masks"
        );
    }

    // ─── Part 2: AAD determinism ─────────────────────────────────────────────
    // The same header fields must always produce the same AAD bytes.

    let auth_key = if data.len() >= 32 { &data[..32] } else { data };

    let (version, mode, frame_idx, epoch) = if data.len() >= 10 {
        (
            data[0],
            data[1],
            u32::from_be_bytes([data[2], data[3], data[4], data[5]]),
            u32::from_be_bytes([data[6], data[7], data[8], data[9]]),
        )
    } else {
        (0x05, 0x00, 0, 0)
    };

    let aad1 = canonicalize_aad(auth_key, version, mode, frame_idx, epoch);
    let aad2 = canonicalize_aad(auth_key, version, mode, frame_idx, epoch);
    assert_eq!(aad1, aad2, "AAD canonicalization must be deterministic");

    // ─── Part 3: Encrypt a "frame payload" with the derived AAD ─────────────
    // This simulates the full header-bind flow:
    //     header → AAD → AEAD seal → ciphertext
    // A mutated AAD must cause decryption to fail (no AAD-omission attack).

    if data.len() >= 56 {
        let enc_key = [data[0]; 32]; // single-byte repeated key is fine for fuzzing
        let nonce = [data[1]; 12];
        let payload = &data[44..data.len().min(100)];

        let ct = aes_gcm_encrypt(&enc_key, &nonce, payload, Some(&aad1));
        if let Ok(ct) = ct {
            // Correct AAD → must succeed
            let ok = aes_gcm_decrypt(&enc_key, &nonce, &ct, Some(&aad2));
            assert!(ok.is_ok(), "Same AAD must allow decryption");

            // Mutated AAD → must fail (AAD omission / tampering)
            let mut bad_aad = aad1.clone();
            if !bad_aad.is_empty() {
                bad_aad[0] ^= 0x01;
                let bad = aes_gcm_decrypt(&enc_key, &nonce, &ct, Some(&bad_aad));
                assert!(bad.is_err(), "Mutated AAD must prevent decryption");
            }

            // No AAD at all → must fail (AAD omission attack)
            let no_aad = aes_gcm_decrypt(&enc_key, &nonce, &ct, None);
            assert!(no_aad.is_err(), "Missing AAD must prevent decryption");
        }
    }

    // ─── Part 4: HKDF with attacker-controlled info ──────────────────────────
    // The `info` field is crafted from the header; must not panic even if huge.
    let long_info = vec![0xFFu8; data.len() % 8192]; // cap at 8 KiB
    let _ = derive_key_hkdf(b"fixed_ikm_for_header_fuzz", None, &long_info, 32);

    // Empty info
    let _ = derive_key_hkdf(b"fixed_ikm", None, b"", 32);

    // Output lengths that span boundary conditions
    for out_len in [0usize, 1, 32, 64, 255] {
        let _ = derive_key_hkdf(data, None, b"fuzz_context", out_len);
    }
});

//! Fuzz target: Hybrid classical + post-quantum decapsulation
//!
//! # Attack classes covered
//! - Hybrid downgrade     → fuzzer supplies only classical or only PQ material
//! - PQ failure fallback  → corrupted / truncated PQ ciphertext
//! - State compromise     → wrong private key used for decap
//! - Nonce reuse          → shared_secret fed into HKDF context, uniqueness tested
//!
//! # PQXDH-style hybrid combiner model (from copilot-instructions.md):
//!   PRK = HMAC-SHA256(0x00*32, classical_ss || pq_ss)
//!   OKM = HKDF-Expand(PRK, "meow_pqxdh_v1" || transcript_hash, 32)
//!
//! # Hard invariants
//! 1. No panic on any byte sequence.
//! 2. Decapsulation with WRONG private key must not produce the same shared secret
//!    as decapsulation with the correct key (for non-trivial inputs).
//! 3. The hybrid combiner requires BOTH secrets; zeroing either component changes
//!    the output key.
//! 4. Wrong-length PQ ciphertext returns Err, not a silently incorrect key.
//!
//! # PQ feature gating
//! When compiled without the `pq` feature the PQ paths are replaced by empty
//! branches; the classical X25519 + HKDF harness still runs.

#![no_main]

use libfuzzer_sys::fuzz_target;
use meow_crypto_rs::pure::{
    derive_key_hkdf, hkdf_extract, hmac_sha256, x25519_exchange, x25519_generate_keypair,
    x25519_public_from_private,
};

#[cfg(feature = "pq")]
use meow_crypto_rs::pure::{mlkem768_decapsulate, mlkem768_encapsulate, mlkem768_keygen};

/// PQXDH-style combiner.
/// classical_ss: 32 bytes from X25519
/// pq_ss:        32 bytes from ML-KEM (or all-zero if classical-only)
/// transcript:   hash of protocol transcript
fn hybrid_combine(classical_ss: &[u8], pq_ss: &[u8], transcript: &[u8]) -> Vec<u8> {
    // Step 1: zero-salt HKDF-Extract over concatenated shared secrets
    let mut ikm = Vec::with_capacity(classical_ss.len() + pq_ss.len());
    ikm.extend_from_slice(classical_ss);
    ikm.extend_from_slice(pq_ss);
    let salt = vec![0u8; 32];
    let prk = hkdf_extract(Some(&salt), &ikm);

    // Step 2: HKDF-Expand with domain-separated info including transcript
    let mut info = b"meow_pqxdh_v1".to_vec();
    info.extend_from_slice(transcript);
    derive_key_hkdf(&prk, None, &info, 32).unwrap_or_else(|_| vec![0u8; 32])
}

fuzz_target!(|data: &[u8]| {
    // ─── Part 1: X25519 key exchange with fuzzer-controlled peer key ──────────
    // Private key bytes are extracted from input; rest is the "peer public key".
    // Must never panic for any combination.

    if data.len() >= 32 {
        let mut priv_bytes = [0u8; 32];
        priv_bytes.copy_from_slice(&data[..32]);
        let peer_pub = &data[32..];

        // Exchange with arbitrary-length peer pub (wrong length must Err)
        let _ = x25519_exchange(&priv_bytes, peer_pub);

        // Derive our own public key from the fuzzed private key (always succeeds)
        let _ = x25519_public_from_private(&priv_bytes);
    }

    // ─── Part 2: Classical-only hybrid combiner ───────────────────────────────
    // Both parties do X25519 DH; the PQ slot is zero-filled.
    {
        let (priv_a, pub_a) = x25519_generate_keypair();
        let (priv_b, pub_b) = x25519_generate_keypair();

        let ss_a = x25519_exchange(&priv_a, &pub_b).expect("valid keypair exchange must succeed");
        let ss_b = x25519_exchange(&priv_b, &pub_a).expect("valid keypair exchange must succeed");
        assert_eq!(ss_a, ss_b, "X25519 DH is not symmetric");

        let pq_zero = [0u8; 32]; // classical-only mode
        let transcript = data;
        let key_a = hybrid_combine(&ss_a, &pq_zero, transcript);
        let key_b = hybrid_combine(&ss_b, &pq_zero, transcript);
        assert_eq!(key_a, key_b, "Hybrid combiner must be symmetric");

        // INVARIANT: zeroing the classical component changes the session key.
        let key_no_classical = hybrid_combine(&pq_zero, &pq_zero, transcript);
        assert_ne!(
            key_a, key_no_classical,
            "Classical secret must contribute to session key"
        );
    }

    // ─── Part 3: Attacker-supplied "shared secret" in combiner ───────────────
    // Fuzzer drives both operands.  Must not panic.
    if data.len() >= 64 {
        let (classical_ss, rest) = data.split_at(32);
        let (pq_ss, transcript) = rest.split_at(32);
        let _key = hybrid_combine(classical_ss, pq_ss, transcript);
    }

    // ─── Part 4: PQ-gated paths ───────────────────────────────────────────────
    #[cfg(feature = "pq")]
    {
        // 4a: Round-trip with genuine keys (sanity gate)
        {
            let (sk, pk) = mlkem768_keygen();
            let enc_result = mlkem768_encapsulate(&pk);
            assert!(
                enc_result.is_ok(),
                "Encapsulate with valid pk must not fail"
            );
            let (ss_enc, ct) = enc_result.unwrap();

            let ss_dec = mlkem768_decapsulate(&sk, &ct);
            assert!(ss_dec.is_ok(), "Decapsulate with valid ct+sk must not fail");
            assert_eq!(ss_enc, ss_dec.unwrap(), "KEM shared secrets must match");
        }

        // 4b: Fuzz the PQ ciphertext (attacker-controlled bytes)
        {
            let (sk, _pk) = mlkem768_keygen();
            // Pass attacker data as ciphertext → must return Err, not panic
            let _ = mlkem768_decapsulate(&sk, data);
        }

        // 4c: Fuzz the public key used for encapsulation
        {
            let _ = mlkem768_encapsulate(data);
        }

        // 4d: Wrong private key must not produce correct shared secret
        {
            let (sk_correct, pk) = mlkem768_keygen();
            let (sk_wrong, _) = mlkem768_keygen();
            let (ss_enc, ct) = mlkem768_encapsulate(&pk).unwrap();

            let ss_correct = mlkem768_decapsulate(&sk_correct, &ct).unwrap();
            let ss_wrong = mlkem768_decapsulate(&sk_wrong, &ct);

            assert_eq!(
                ss_enc, ss_correct,
                "Correct key must recover encapsulated secret"
            );
            // Wrong key: either Err or a *different* shared secret.
            if let Ok(ss) = ss_wrong {
                assert_ne!(
                    ss, ss_correct,
                    "Wrong private key must not produce the same shared secret"
                );
            }
        }

        // 4e: Full hybrid with real PQ secrets; classical zeroed = downgrade check
        {
            let (priv_a, pub_a) = x25519_generate_keypair();
            let (priv_b, pub_b) = x25519_generate_keypair();
            let classical_a = x25519_exchange(&priv_a, &pub_b).unwrap();
            let classical_b = x25519_exchange(&priv_b, &pub_a).unwrap();

            let (sk_kem, pk_kem) = mlkem768_keygen();
            let (pq_ss_enc, ct) = mlkem768_encapsulate(&pk_kem).unwrap();
            let pq_ss_dec = mlkem768_decapsulate(&sk_kem, &ct).unwrap();
            assert_eq!(pq_ss_enc, pq_ss_dec);

            let transcript = data;
            let full_key_a = hybrid_combine(&classical_a, &pq_ss_enc, transcript);
            let full_key_b = hybrid_combine(&classical_b, &pq_ss_dec, transcript);
            assert_eq!(
                full_key_a, full_key_b,
                "Full hybrid session keys must match"
            );

            // DOWNGRADE CHECK: removing PQ component must change the key.
            let downgrade_key = hybrid_combine(&classical_a, &[0u8; 32], transcript);
            assert_ne!(
                full_key_a, downgrade_key,
                "PQ secret must contribute to hybrid session key (downgrade rejected)"
            );
        }
    }

    // ─── Part 5: HMAC as transcript binder (commitment tag simulation) ────────
    // commitment = HMAC-SHA256(binding_key, classical_pub || pq_ct_hash || epoch)
    if data.len() >= 4 {
        let binding_key = b"meow_commitment_v1";
        let tag1 = hmac_sha256(binding_key, data);
        let tag2 = hmac_sha256(binding_key, data);
        assert_eq!(tag1, tag2, "Commitment tag must be deterministic");
        // Tags must be 32 bytes or we have a contract violation
        if let Ok(ref t) = tag1 {
            assert_eq!(t.len(), 32);
        }
    }
});

//! Fuzz target: Per-frame symmetric ratchet (MSR v2.0 model)
//!
//! # Attack classes covered
//! - Replay               → re-feeding a previously processed frame index
//! - State compromise     → advancing beyond a compromised frame must not
//!                          allow derivation of earlier keys (forward secrecy)
//! - Nonce reuse          → each ratchet step must produce a unique message key
//! - Ratchet monotonicity → advancing the ratchet must be irreversible
//!
//! # Ratchet model (from copilot-instructions.md MSR v1.2 / v2.0):
//!   chain_key[n+1] = HKDF-SHA256(chain_key[n], "meow_ratchet_chain_v1", 32)
//!   message_key[n] = HKDF-SHA256(chain_key[n], "meow_ratchet_msg_v1",   32)
//!   commitment[n]  = HMAC-SHA256(message_key[n], "meow_commitment")
//!
//! This file models that ratchet independently of any Rust module so it can
//! be compiled today; replace `advance_ratchet` with the real function signature
//! when the ratchet module lands in rust_crypto.
//!
//! # Hard invariants
//! 1. No panic.
//! 2. message_key[n] != message_key[m] for n != m (nonce uniqueness).
//! 3. chain_key[n]   != chain_key[n+1] (ratchet is not identity).
//! 4. There is no function to go from chain_key[n+1] back to chain_key[n].
//!    (We verify this by asserting that re-deriving from a future state never
//!     matches any key produced before that state.)

#![no_main]

use libfuzzer_sys::fuzz_target;
use meow_crypto_rs::pure::{derive_key_hkdf, hmac_sha256, hmac_sha256_verify};

const CHAIN_DOMAIN: &[u8] = b"meow_ratchet_chain_v1";
const MSG_DOMAIN: &[u8] = b"meow_ratchet_msg_v1";
const COMMIT_DOMAIN: &[u8] = b"meow_ratchet_commit_v1";
const HEADER_DOMAIN: &[u8] = b"meow_ratchet_header_v1";

/// One ratchet state.
#[derive(Clone, Debug)]
struct RatchetState {
    chain_key: Vec<u8>,
    frame_idx: u32,
}

impl RatchetState {
    fn new(root_key: &[u8]) -> Self {
        RatchetState {
            chain_key: root_key.to_vec(),
            frame_idx: 0,
        }
    }

    /// Advance the ratchet by one step.
    /// Returns (message_key, commitment_tag, header_mask_20b).
    /// The chain_key is mutated; the previous value is irrecoverable.
    fn advance(&mut self) -> (Vec<u8>, Vec<u8>, Vec<u8>) {
        // Derive message key from current chain state
        let mut msg_info = MSG_DOMAIN.to_vec();
        msg_info.extend_from_slice(&self.frame_idx.to_be_bytes());
        let message_key =
            derive_key_hkdf(&self.chain_key, None, &msg_info, 32).unwrap_or_else(|_| vec![0u8; 32]);

        // Commitment tag: HMAC-SHA256(message_key, "meow_ratchet_commit_v1" || frame_idx)
        let mut commit_msg = COMMIT_DOMAIN.to_vec();
        commit_msg.extend_from_slice(&self.frame_idx.to_be_bytes());
        let commitment = hmac_sha256(&message_key, &commit_msg).unwrap_or_else(|_| vec![0u8; 32]);

        // Header mask (20 bytes: 4 for encrypted index, 16 for commitment tag XOR)
        let mut hdr_info = HEADER_DOMAIN.to_vec();
        hdr_info.extend_from_slice(&self.frame_idx.to_be_bytes());
        let header_mask =
            derive_key_hkdf(&self.chain_key, None, &hdr_info, 20).unwrap_or_else(|_| vec![0u8; 20]);

        // Advance chain key AFTER deriving message key (forward secrecy)
        let mut chain_info = CHAIN_DOMAIN.to_vec();
        chain_info.extend_from_slice(&self.frame_idx.to_be_bytes());
        let next_chain = derive_key_hkdf(&self.chain_key, None, &chain_info, 32)
            .unwrap_or_else(|_| vec![0u8; 32]);

        self.chain_key = next_chain;
        self.frame_idx += 1;

        (message_key, commitment, header_mask)
    }
}

fuzz_target!(|data: &[u8]| {
    // Use the fuzzer input as the root key; any length is valid (HKDF handles it)
    let root_key = if data.is_empty() {
        b"default_root_key".as_ref()
    } else {
        data
    };

    // ─── Scenario A: sequential ratchet steps ─────────────────────────────────
    // Derive N steps and collect all message_keys + chain_keys.
    // N is bounded at 64 to keep the fuzz run time sane.
    let steps: usize = 1 + (data.len() % 64);

    let mut state = RatchetState::new(root_key);
    let mut message_keys: Vec<Vec<u8>> = Vec::with_capacity(steps);
    let mut commitments: Vec<Vec<u8>> = Vec::with_capacity(steps);
    let mut header_masks: Vec<Vec<u8>> = Vec::with_capacity(steps);
    let mut chain_snapshots: Vec<Vec<u8>> = Vec::with_capacity(steps);

    chain_snapshots.push(state.chain_key.clone()); // snapshot before step 0

    for _ in 0..steps {
        let (mk, cm, hm) = state.advance();
        message_keys.push(mk);
        commitments.push(cm);
        header_masks.push(hm);
        chain_snapshots.push(state.chain_key.clone()); // snapshot after this step
    }

    // INVARIANT: ratchet is not the identity – chain_key must change each step.
    for i in 0..steps {
        assert_ne!(
            chain_snapshots[i],
            chain_snapshots[i + 1],
            "Chain key must change at every ratchet step (step {})",
            i
        );
    }

    // INVARIANT: message keys must all be unique (nonce uniqueness).
    for i in 0..steps {
        for j in (i + 1)..steps {
            assert_ne!(
                message_keys[i], message_keys[j],
                "Message keys at steps {} and {} must be distinct",
                i, j
            );
        }
    }

    // INVARIANT: commitment tags must all be 32 bytes.
    for (i, cm) in commitments.iter().enumerate() {
        assert_eq!(cm.len(), 32, "Commitment at step {} must be 32 bytes", i);
    }

    // INVARIANT: header masks must all be 20 bytes.
    for (i, hm) in header_masks.iter().enumerate() {
        assert_eq!(hm.len(), 20, "Header mask at step {} must be 20 bytes", i);
    }

    // ─── Scenario B: replay detection simulation──────────────────────────────
    // Simulate a receiver that tracks seen frame indices.
    // Re-presenting frame N must be detectable via the commitment tag.
    if steps >= 2 {
        // Re-derive step 0 from the original root key (attacker replays frame 0)
        let mut replayed = RatchetState::new(root_key);
        let (replay_mk, replay_cm, _) = replayed.advance();

        // The commitment tag for frame 0 must match what we computed above,
        // and a receiver's seen-set check catches the replay.
        assert_eq!(
            replay_cm, commitments[0],
            "Re-derived commitment for frame 0 must be deterministic (replay detectable)"
        );

        // Verify that the commitment tag for frame 0 authenticates correctly.
        let mut commit_msg = COMMIT_DOMAIN.to_vec();
        commit_msg.extend_from_slice(&0u32.to_be_bytes());
        let valid = hmac_sha256_verify(&replay_mk, &commit_msg, &replay_cm).unwrap_or(false);
        assert!(
            valid,
            "Commitment tag must verify with the matching message key"
        );

        // Verification with a WRONG key must fail (prevents forgery).
        let wrong_key = vec![0xFFu8; 32];
        let invalid = hmac_sha256_verify(&wrong_key, &commit_msg, &replay_cm).unwrap_or(true); // default true means "forged" – OK: also fails
        assert!(!invalid, "Commitment tag must not verify with wrong key");
    }

    // ─── Scenario C: post-compromise forward secrecy ──────────────────────────
    // An adversary who learns chain_key[k] must not be able to derive
    // message_key[k-1] (past keys are erased).
    //
    // We model this by showing that deriving backwards is impossible:
    // chain_key[k] cannot be inverted to chain_key[k-1] (HKDF is one-way).
    // We can only assert that re-running the ratchet from chain_key[k] yields
    // the same *future* keys but NOT the past ones.
    if steps >= 3 {
        let compromised_at = steps / 2;
        let compromised_chain_key = chain_snapshots[compromised_at].clone();

        // Re-run the ratchet from the compromised state.
        let mut future_state = RatchetState {
            chain_key: compromised_chain_key,
            frame_idx: compromised_at as u32,
        };
        let (future_mk, _, _) = future_state.advance();

        // The future key must match what the honest ratchet produced.
        assert_eq!(
            future_mk, message_keys[compromised_at],
            "Future keys must be recoverable from compromised state"
        );

        // Past keys must NOT be derivable from the compromised chain key.
        // We confirm by showing past keys != future keys (they were derived
        // from prior chain states that no longer exist).
        for past in 0..compromised_at {
            assert_ne!(
                future_mk, message_keys[past],
                "Future key at {} must not match past key at {} (PCS violated)",
                compromised_at, past
            );
        }
    }

    // ─── Scenario D: attacker-supplied commitment forgery attempt ─────────────
    // Fuzzer provides bytes as a forged commitment; verification must fail.
    if data.len() >= 32 && steps >= 1 {
        let forged_tag = &data[..32];
        let mut commit_msg = COMMIT_DOMAIN.to_vec();
        commit_msg.extend_from_slice(&0u32.to_be_bytes());

        let is_valid =
            hmac_sha256_verify(&message_keys[0], &commit_msg, forged_tag).unwrap_or(false);

        // Only if the fuzzer happened to supply the exact correct tag will this pass.
        // That requires guessing 32 bytes = 256-bit preimage.  We don't assert false
        // here because data COULD be the correct tag; we assert no panic only.
        let _ = is_valid;
    }
});

//! Opaque handle registry for secret key material.
//!
//! All secret-bearing state lives exclusively in Rust. Python receives only
//! opaque integer handles that index into a thread-safe registry.
//! Handles cannot be introspected from Python — no dump_state, no serialize.
//!
//! # Security invariants
//! - Secret bytes never cross the FFI boundary.
//! - All secret material is zeroized on drop (via `zeroize` crate).
//! - Handle IDs are sequential u64; cannot be forged to access another slot.
//! - Registry is bounded (MAX_HANDLES = 65536) to prevent resource exhaustion.

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::Mutex;

use aes_gcm::{
    aead::{Aead, KeyInit as AeadKeyInit, Payload},
    Aes256Gcm, Nonce,
};
use hkdf::Hkdf;
use hmac::{Hmac, Mac as HmacMac};
use sha2::Sha256;
use subtle::ConstantTimeEq;
use x25519_dalek::{PublicKey, StaticSecret};
use zeroize::Zeroize;

type HmacSha256 = Hmac<Sha256>;

/// Maximum number of live handles (prevents DoS).
const MAX_HANDLES: usize = 65536;

// ─── Error type ─────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum HandleError {
    InvalidHandle,
    RegistryFull,
    InvalidKeyLength { expected: usize, got: usize },
    InvalidNonceLength { expected: usize, got: usize },
    CiphertextTooShort,
    EncryptionFailed,
    DecryptionFailed,
    HkdfFailed(String),
    InvalidPrkLength,
    AuthenticationFailed,
    InvalidPublicKeyLength,
    HandleTypeMismatch,
}

impl std::fmt::Display for HandleError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            HandleError::InvalidHandle => write!(f, "Invalid or expired handle"),
            HandleError::RegistryFull => write!(f, "Handle registry full (max {})", MAX_HANDLES),
            HandleError::InvalidKeyLength { expected, got } => {
                write!(f, "Key must be {} bytes, got {}", expected, got)
            }
            HandleError::InvalidNonceLength { expected, got } => {
                write!(f, "Nonce must be {} bytes, got {}", expected, got)
            }
            HandleError::CiphertextTooShort => write!(f, "Ciphertext too short"),
            HandleError::EncryptionFailed => write!(f, "Encryption failed"),
            HandleError::DecryptionFailed => write!(f, "Decryption failed - authentication error"),
            HandleError::HkdfFailed(s) => write!(f, "HKDF failed: {}", s),
            HandleError::InvalidPrkLength => write!(f, "Invalid PRK length"),
            HandleError::AuthenticationFailed => write!(f, "Authentication failed"),
            HandleError::InvalidPublicKeyLength => write!(f, "Public key must be 32 bytes"),
            HandleError::HandleTypeMismatch => write!(f, "Handle type mismatch"),
        }
    }
}

// ─── Handle ID ──────────────────────────────────────────────────────────────

/// Opaque handle ID. Python sees only this integer.
pub type HandleId = u64;

static NEXT_HANDLE_ID: AtomicU64 = AtomicU64::new(1);

fn next_id() -> HandleId {
    NEXT_HANDLE_ID.fetch_add(1, Ordering::SeqCst)
}

// ─── Secret material containers (all Zeroize on Drop) ───────────────────────

/// A 32-byte symmetric key that zeroizes on drop.
#[derive(Clone)]
struct SecretKey {
    bytes: [u8; 32],
}

impl SecretKey {
    fn new(src: &[u8]) -> Result<Self, HandleError> {
        if src.len() != 32 {
            return Err(HandleError::InvalidKeyLength {
                expected: 32,
                got: src.len(),
            });
        }
        let mut bytes = [0u8; 32];
        bytes.copy_from_slice(src);
        Ok(Self { bytes })
    }

    fn as_bytes(&self) -> &[u8; 32] {
        &self.bytes
    }
}

impl Drop for SecretKey {
    fn drop(&mut self) {
        self.bytes.zeroize();
    }
}

/// X25519 private key container (zeroizes on drop).
struct X25519Private {
    bytes: [u8; 32],
}

impl X25519Private {
    fn generate() -> (Self, [u8; 32]) {
        use rand::rngs::OsRng;
        let secret = StaticSecret::random_from_rng(OsRng);
        let public = PublicKey::from(&secret);
        let mut bytes = [0u8; 32];
        bytes.copy_from_slice(secret.as_bytes());
        (Self { bytes }, *public.as_bytes())
    }

    fn from_bytes(private_bytes: &[u8; 32]) -> Self {
        Self {
            bytes: *private_bytes,
        }
    }

    fn exchange(&self, peer_public: &[u8; 32]) -> [u8; 32] {
        let secret = StaticSecret::from(self.bytes);
        let public = PublicKey::from(*peer_public);
        let shared = secret.diffie_hellman(&public);
        *shared.as_bytes()
    }

    fn public_key(&self) -> [u8; 32] {
        let secret = StaticSecret::from(self.bytes);
        let public = PublicKey::from(&secret);
        *public.as_bytes()
    }
}

impl Drop for X25519Private {
    fn drop(&mut self) {
        self.bytes.zeroize();
    }
}

// ─── Handle payload types ───────────────────────────────────────────────────

/// Session state: holds encryption key, MAC key, nonce state.
/// Used for AES-GCM or AES-CTR + HMAC based sessions.
#[allow(dead_code)] // Fields read when session operations are called via M1 migration
pub struct SessionState {
    enc_key: SecretKey,
    mac_key: Option<SecretKey>,
    nonce_counter: u64,
}

/// Ratchet state: chain key, root key, optional ephemeral X25519.
#[allow(dead_code)] // Fields read when ratchet step/advance operations are called via M2 migration
pub struct RatchetState {
    root_key: SecretKey,
    chain_key: SecretKey,
    step_index: u64,
    ephemeral_private: Option<X25519Private>,
    /// Cached skip keys: (frame_index -> message_key)
    skip_keys: HashMap<u64, SecretKey>,
}

/// Stream state: AES-CTR key + MAC key for streaming encrypt/decrypt.
pub struct StreamState {
    enc_key: SecretKey,
    mac_key: SecretKey,
    nonce: [u8; 16],
    byte_offset: u64,
}

/// An HMAC key handle for frame/message authentication.
pub struct HmacKeyState {
    key: SecretKey,
}

/// Enum wrapping all handle types.
#[allow(dead_code)] // HmacKey variant used in handle_hmac_* operations
enum HandlePayload {
    Session(SessionState),
    Ratchet(RatchetState),
    Stream(StreamState),
    HmacKey(HmacKeyState),
    SymmetricKey(SecretKey),
    X25519Key(X25519Private),
}

impl Drop for HandlePayload {
    fn drop(&mut self) {
        // Inner types all implement Zeroize-on-Drop via their own Drop impls
    }
}

// ─── Global registry ────────────────────────────────────────────────────────

lazy_static::lazy_static! {
    static ref REGISTRY: Mutex<HashMap<HandleId, HandlePayload>> = Mutex::new(HashMap::new());
}

fn insert_handle(payload: HandlePayload) -> Result<HandleId, HandleError> {
    let mut reg = REGISTRY.lock().unwrap();
    if reg.len() >= MAX_HANDLES {
        return Err(HandleError::RegistryFull);
    }
    let id = next_id();
    reg.insert(id, payload);
    Ok(id)
}

fn remove_handle(id: HandleId) -> Result<HandlePayload, HandleError> {
    let mut reg = REGISTRY.lock().unwrap();
    reg.remove(&id).ok_or(HandleError::InvalidHandle)
}

fn with_handle<F, R>(id: HandleId, f: F) -> Result<R, HandleError>
where
    F: FnOnce(&HandlePayload) -> Result<R, HandleError>,
{
    let reg = REGISTRY.lock().unwrap();
    let payload = reg.get(&id).ok_or(HandleError::InvalidHandle)?;
    f(payload)
}

fn with_handle_mut<F, R>(id: HandleId, f: F) -> Result<R, HandleError>
where
    F: FnOnce(&mut HandlePayload) -> Result<R, HandleError>,
{
    let mut reg = REGISTRY.lock().unwrap();
    let payload = reg.get_mut(&id).ok_or(HandleError::InvalidHandle)?;
    f(payload)
}

// ─── Public API: Key derivation ─────────────────────────────────────────────

/// Derive a key via Argon2id and store it as an opaque handle.
/// Returns handle ID — Python never sees the key bytes.
pub fn handle_derive_key_argon2id(
    password: &[u8],
    salt: &[u8],
    memory_kib: u32,
    iterations: u32,
    parallelism: u32,
) -> Result<HandleId, HandleError> {
    use argon2::{Algorithm, Argon2, Params, Version};

    if salt.len() != 16 {
        return Err(HandleError::InvalidKeyLength {
            expected: 16,
            got: salt.len(),
        });
    }

    let params = Params::new(memory_kib, iterations, parallelism, Some(32))
        .map_err(|e| HandleError::HkdfFailed(format!("Invalid Argon2 params: {}", e)))?;
    let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);

    let mut output = [0u8; 32];
    argon2
        .hash_password_into(password, salt, &mut output)
        .map_err(|e| HandleError::HkdfFailed(format!("Argon2id failed: {}", e)))?;

    let key = SecretKey::new(&output)?;
    output.zeroize();
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// Derive a key via HKDF and store as opaque handle.
/// `ikm_handle` must be an existing key handle.
pub fn handle_derive_hkdf(
    ikm_handle: HandleId,
    salt: &[u8],
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let ikm_bytes = with_handle(ikm_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::Session(s) => Ok(s.enc_key.as_bytes().to_vec()),
        HandlePayload::Ratchet(r) => Ok(r.chain_key.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let salt_opt: Option<&[u8]> = if salt.is_empty() { None } else { Some(salt) };
    let hkdf = Hkdf::<Sha256>::new(salt_opt, &ikm_bytes);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    // Truncate or pad to 32 bytes for key storage
    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// Derive a key via HKDF(password || keyfile) → Argon2id and store as handle.
///
/// This performs the full keyfile-combined KDF without any intermediate secret
/// bytes crossing the FFI boundary:
///   1. HKDF(password || keyfile, domain_sep, "password_keyfile_combine", 64)
///   2. Argon2id(combined, salt, params) → 32-byte key
///   3. Store key as opaque handle
///
/// All intermediate buffers are zeroized.
#[allow(clippy::too_many_arguments)]
pub fn handle_derive_key_argon2id_with_keyfile(
    password: &[u8],
    keyfile: &[u8],
    keyfile_domain_sep: &[u8],
    salt: &[u8],
    memory_kib: u32,
    iterations: u32,
    parallelism: u32,
) -> Result<HandleId, HandleError> {
    use argon2::{Algorithm, Argon2, Params, Version};

    if salt.len() != 16 {
        return Err(HandleError::InvalidKeyLength {
            expected: 16,
            got: salt.len(),
        });
    }

    // Step 1: HKDF(password || keyfile, domain_sep, "password_keyfile_combine", 64)
    let mut ikm = Vec::with_capacity(password.len() + keyfile.len());
    ikm.extend_from_slice(password);
    ikm.extend_from_slice(keyfile);

    let hkdf = Hkdf::<Sha256>::new(Some(keyfile_domain_sep), &ikm);
    let mut combined = vec![0u8; 64];
    hkdf.expand(b"password_keyfile_combine", &mut combined)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;
    ikm.zeroize();

    // Step 2: Argon2id(combined, salt, params) → 32-byte key
    let params = Params::new(memory_kib, iterations, parallelism, Some(32))
        .map_err(|e| HandleError::HkdfFailed(format!("Invalid Argon2 params: {}", e)))?;
    let argon2 = Argon2::new(Algorithm::Argon2id, Version::V0x13, params);

    let mut output = [0u8; 32];
    argon2
        .hash_password_into(&combined, salt, &mut output)
        .map_err(|e| HandleError::HkdfFailed(format!("Argon2id failed: {}", e)))?;
    combined.zeroize();

    let key = SecretKey::new(&output)?;
    output.zeroize();
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// Derive HKDF from a key handle and return the raw derived bytes.
/// USE ONLY for non-secret derived values (nonces, header masks, AAD components).
/// For secret derived keys, use handle_derive_hkdf() which returns a handle.
pub fn handle_derive_hkdf_bytes(
    ikm_handle: HandleId,
    salt: &[u8],
    info: &[u8],
    output_len: usize,
) -> Result<Vec<u8>, HandleError> {
    let ikm_bytes = with_handle(ikm_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::Session(s) => Ok(s.enc_key.as_bytes().to_vec()),
        HandlePayload::Ratchet(r) => Ok(r.chain_key.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let salt_opt: Option<&[u8]> = if salt.is_empty() { None } else { Some(salt) };
    let hkdf = Hkdf::<Sha256>::new(salt_opt, &ikm_bytes);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    // Return raw bytes (for non-secret derived values like nonces)
    Ok(okm)
}

/// Derive HKDF from raw IKM bytes (for initial key material from password).
pub fn handle_derive_hkdf_raw(
    ikm: &[u8],
    salt: &[u8],
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let salt_opt: Option<&[u8]> = if salt.is_empty() { None } else { Some(salt) };
    let hkdf = Hkdf::<Sha256>::new(salt_opt, ikm);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

// ─── Public API: Encryption/Decryption ──────────────────────────────────────

/// Encrypt with AES-256-GCM using a key handle. Returns ciphertext (with tag).
/// The key never leaves Rust.
pub fn handle_aes_gcm_encrypt(
    key_handle: HandleId,
    nonce: &[u8],
    plaintext: &[u8],
    aad: Option<&[u8]>,
) -> Result<Vec<u8>, HandleError> {
    if nonce.len() != 12 {
        return Err(HandleError::InvalidNonceLength {
            expected: 12,
            got: nonce.len(),
        });
    }

    with_handle(key_handle, |payload| {
        let key_bytes = match payload {
            HandlePayload::SymmetricKey(k) => k.as_bytes(),
            HandlePayload::Session(s) => s.enc_key.as_bytes(),
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        let cipher =
            Aes256Gcm::new_from_slice(key_bytes).map_err(|_| HandleError::EncryptionFailed)?;
        let nonce_arr = Nonce::from_slice(nonce);

        let result = if let Some(aad_data) = aad {
            cipher.encrypt(
                nonce_arr,
                Payload {
                    msg: plaintext,
                    aad: aad_data,
                },
            )
        } else {
            cipher.encrypt(nonce_arr, plaintext)
        };

        result.map_err(|_| HandleError::EncryptionFailed)
    })
}

/// Decrypt with AES-256-GCM using a key handle.
/// Returns plaintext ONLY if authentication succeeds. Fail-closed.
pub fn handle_aes_gcm_decrypt(
    key_handle: HandleId,
    nonce: &[u8],
    ciphertext: &[u8],
    aad: Option<&[u8]>,
) -> Result<Vec<u8>, HandleError> {
    if nonce.len() != 12 {
        return Err(HandleError::InvalidNonceLength {
            expected: 12,
            got: nonce.len(),
        });
    }
    if ciphertext.len() < 16 {
        return Err(HandleError::CiphertextTooShort);
    }

    with_handle(key_handle, |payload| {
        let key_bytes = match payload {
            HandlePayload::SymmetricKey(k) => k.as_bytes(),
            HandlePayload::Session(s) => s.enc_key.as_bytes(),
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        let cipher =
            Aes256Gcm::new_from_slice(key_bytes).map_err(|_| HandleError::DecryptionFailed)?;
        let nonce_arr = Nonce::from_slice(nonce);

        let result = if let Some(aad_data) = aad {
            cipher.decrypt(
                nonce_arr,
                Payload {
                    msg: ciphertext,
                    aad: aad_data,
                },
            )
        } else {
            cipher.decrypt(nonce_arr, ciphertext)
        };

        result.map_err(|_| HandleError::DecryptionFailed)
    })
}

/// Compute HMAC-SHA256 using a key handle. Returns the tag bytes.
pub fn handle_hmac_sha256(key_handle: HandleId, message: &[u8]) -> Result<Vec<u8>, HandleError> {
    with_handle(key_handle, |payload| {
        let key_bytes = match payload {
            HandlePayload::SymmetricKey(k) => k.as_bytes(),
            HandlePayload::HmacKey(h) => h.key.as_bytes(),
            HandlePayload::Session(s) => s
                .mac_key
                .as_ref()
                .map(|k| k.as_bytes())
                .ok_or(HandleError::HandleTypeMismatch)?,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        let mut mac = <HmacSha256 as HmacMac>::new_from_slice(key_bytes).map_err(|_| {
            HandleError::InvalidKeyLength {
                expected: 32,
                got: 0,
            }
        })?;
        mac.update(message);
        let result = mac.finalize();
        Ok(result.into_bytes().to_vec())
    })
}

/// Verify HMAC-SHA256 in constant time using a key handle.
/// Returns Ok(true) or Ok(false). Never leaks the key.
pub fn handle_hmac_sha256_verify(
    key_handle: HandleId,
    message: &[u8],
    expected_tag: &[u8],
) -> Result<bool, HandleError> {
    let computed = handle_hmac_sha256(key_handle, message)?;
    if computed.len() != expected_tag.len() {
        return Ok(false);
    }
    Ok(computed.as_slice().ct_eq(expected_tag).into())
}

/// Compute HMAC-SHA256 with the effective key = `prefix || handle_key_bytes`.
///
/// This enables domain-separated HMAC (e.g. manifest authentication:
/// `HMAC(MANIFEST_HMAC_KEY_PREFIX || enc_key, manifest_bytes)`) without ever
/// exporting the secret key to Python.
///
/// All temporary key material is zeroized before returning.
pub fn handle_hmac_sha256_prefixed(
    key_handle: HandleId,
    prefix: &[u8],
    message: &[u8],
) -> Result<Vec<u8>, HandleError> {
    with_handle(key_handle, |payload| {
        let key_bytes = match payload {
            HandlePayload::SymmetricKey(k) => k.as_bytes(),
            HandlePayload::HmacKey(h) => h.key.as_bytes(),
            HandlePayload::Session(s) => s
                .mac_key
                .as_ref()
                .map(|k| k.as_bytes())
                .ok_or(HandleError::HandleTypeMismatch)?,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        // Build prefix || key_bytes — the combined HMAC key
        let mut hmac_key = Vec::with_capacity(prefix.len() + key_bytes.len());
        hmac_key.extend_from_slice(prefix);
        hmac_key.extend_from_slice(key_bytes);

        let mut mac = <HmacSha256 as HmacMac>::new_from_slice(&hmac_key).map_err(|_| {
            HandleError::InvalidKeyLength {
                expected: 32,
                got: hmac_key.len(),
            }
        })?;
        mac.update(message);
        let tag = mac.finalize().into_bytes().to_vec();

        // Zeroize the concatenated key material
        hmac_key.zeroize();

        Ok(tag)
    })
}

/// Verify HMAC-SHA256 with prefixed key in constant time.
/// Effective key = `prefix || handle_key_bytes`.
pub fn handle_hmac_sha256_prefixed_verify(
    key_handle: HandleId,
    prefix: &[u8],
    message: &[u8],
    expected_tag: &[u8],
) -> Result<bool, HandleError> {
    let computed = handle_hmac_sha256_prefixed(key_handle, prefix, message)?;
    if computed.len() != expected_tag.len() {
        return Ok(false);
    }
    Ok(computed.as_slice().ct_eq(expected_tag).into())
}

// ─── Public API: X25519 ────────────────────────────────────────────────────

/// Generate X25519 keypair. Private key stays in Rust handle.
/// Returns (handle_id, public_key_bytes).
pub fn handle_x25519_generate() -> Result<(HandleId, [u8; 32]), HandleError> {
    let (private, public) = X25519Private::generate();
    let id = insert_handle(HandlePayload::X25519Key(private))?;
    Ok((id, public))
}

/// Perform X25519 key exchange. Private key never leaves Rust.
/// Shared secret is stored as a new key handle.
pub fn handle_x25519_exchange(
    private_handle: HandleId,
    peer_public: &[u8],
) -> Result<HandleId, HandleError> {
    if peer_public.len() != 32 {
        return Err(HandleError::InvalidPublicKeyLength);
    }
    let mut pub_bytes = [0u8; 32];
    pub_bytes.copy_from_slice(peer_public);

    let shared = with_handle(private_handle, |payload| match payload {
        HandlePayload::X25519Key(k) => Ok(k.exchange(&pub_bytes)),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let key = SecretKey::new(&shared)?;
    let mut shared_mut = shared;
    shared_mut.zeroize();
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// Get public key from an X25519 private key handle.
pub fn handle_x25519_public(handle: HandleId) -> Result<[u8; 32], HandleError> {
    with_handle(handle, |payload| match payload {
        HandlePayload::X25519Key(k) => Ok(k.public_key()),
        _ => Err(HandleError::HandleTypeMismatch),
    })
}

/// Import raw X25519 private key bytes into an opaque handle.
/// Private key bytes are copied into Rust and zeroized on drop.
pub fn handle_import_x25519_private(private_bytes: &[u8]) -> Result<HandleId, HandleError> {
    if private_bytes.len() != 32 {
        return Err(HandleError::InvalidKeyLength {
            expected: 32,
            got: private_bytes.len(),
        });
    }
    let mut bytes = [0u8; 32];
    bytes.copy_from_slice(private_bytes);
    let key = X25519Private::from_bytes(&bytes);
    bytes.zeroize();
    insert_handle(HandlePayload::X25519Key(key))
}

// ─── Public API: Session management ─────────────────────────────────────────

/// Create a session from an encryption key handle and optional MAC key handle.
pub fn handle_session_new(
    enc_key_handle: HandleId,
    mac_key_handle: Option<HandleId>,
) -> Result<HandleId, HandleError> {
    let enc_key = with_handle(enc_key_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.clone()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let mac_key = if let Some(mh) = mac_key_handle {
        let mk = with_handle(mh, |payload| match payload {
            HandlePayload::SymmetricKey(k) => Ok(k.clone()),
            HandlePayload::HmacKey(h) => Ok(h.key.clone()),
            _ => Err(HandleError::HandleTypeMismatch),
        })?;
        Some(mk)
    } else {
        None
    };

    insert_handle(HandlePayload::Session(SessionState {
        enc_key,
        mac_key,
        nonce_counter: 0,
    }))
}

// ─── Public API: Stream state ───────────────────────────────────────────────

/// Create a stream handle from enc_key_handle + salt for MAC key derivation.
pub fn handle_stream_new(
    enc_key_handle: HandleId,
    nonce: &[u8],
    mac_domain: &[u8],
) -> Result<HandleId, HandleError> {
    if nonce.len() != 16 {
        return Err(HandleError::InvalidNonceLength {
            expected: 16,
            got: nonce.len(),
        });
    }

    let enc_key = with_handle(enc_key_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.clone()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    // Derive MAC key via HKDF(enc_key, nonce, mac_domain)
    let hkdf = Hkdf::<Sha256>::new(Some(nonce), enc_key.as_bytes());
    let mut mac_bytes = [0u8; 32];
    hkdf.expand(mac_domain, &mut mac_bytes)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;
    let mac_key = SecretKey { bytes: mac_bytes };

    let mut nonce_arr = [0u8; 16];
    nonce_arr.copy_from_slice(nonce);

    insert_handle(HandlePayload::Stream(StreamState {
        enc_key,
        mac_key,
        nonce: nonce_arr,
        byte_offset: 0,
    }))
}

/// Stream encrypt: AES-CTR encrypt + compute HMAC over (nonce || ciphertext).
pub fn handle_stream_encrypt(
    stream_handle: HandleId,
    plaintext: &[u8],
) -> Result<(Vec<u8>, Vec<u8>), HandleError> {
    with_handle_mut(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        // AES-CTR encrypt
        let ciphertext = crypto_core::pure_crypto::aes_ctr_crypt(
            stream.enc_key.as_bytes(),
            &stream.nonce,
            plaintext,
            stream.byte_offset,
        )
        .map_err(|_| HandleError::EncryptionFailed)?;

        stream.byte_offset += plaintext.len() as u64;

        // Compute MAC over nonce || ciphertext
        let mut mac_input = Vec::with_capacity(16 + ciphertext.len());
        mac_input.extend_from_slice(&stream.nonce);
        mac_input.extend_from_slice(&ciphertext);

        let mut mac = <HmacSha256 as HmacMac>::new_from_slice(stream.mac_key.as_bytes())
            .map_err(|_| HandleError::EncryptionFailed)?;
        mac.update(&mac_input);
        let tag = mac.finalize().into_bytes().to_vec();

        Ok((ciphertext, tag))
    })
}

/// Stream decrypt: verify HMAC then AES-CTR decrypt. Fail-closed.
pub fn handle_stream_decrypt(
    stream_handle: HandleId,
    ciphertext: &[u8],
    expected_mac: &[u8],
) -> Result<Vec<u8>, HandleError> {
    with_handle_mut(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        // Compute and verify MAC BEFORE decryption
        let mut mac_input = Vec::with_capacity(16 + ciphertext.len());
        mac_input.extend_from_slice(&stream.nonce);
        mac_input.extend_from_slice(ciphertext);

        let mut mac = <HmacSha256 as HmacMac>::new_from_slice(stream.mac_key.as_bytes())
            .map_err(|_| HandleError::DecryptionFailed)?;
        mac.update(&mac_input);
        let computed = mac.finalize().into_bytes();

        let is_valid: bool = computed.as_slice().ct_eq(expected_mac).into();
        if !is_valid {
            return Err(HandleError::AuthenticationFailed);
        }

        // MAC verified — now decrypt
        let plaintext = crypto_core::pure_crypto::aes_ctr_crypt(
            stream.enc_key.as_bytes(),
            &stream.nonce,
            ciphertext,
            stream.byte_offset,
        )
        .map_err(|_| HandleError::DecryptionFailed)?;

        stream.byte_offset += ciphertext.len() as u64;
        Ok(plaintext)
    })
}

// ─── Public API: Ratchet ────────────────────────────────────────────────────

/// Create a ratchet from a root key handle.
pub fn handle_ratchet_new(
    root_key_handle: HandleId,
    salt: &[u8],
    root_info: &[u8],
) -> Result<HandleId, HandleError> {
    let root_bytes = with_handle(root_key_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(*k.as_bytes()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    // Derive initial chain key from root key
    let hkdf = Hkdf::<Sha256>::new(Some(salt), &root_bytes);
    let mut chain_bytes = [0u8; 32];
    hkdf.expand(root_info, &mut chain_bytes)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let root_key = SecretKey { bytes: root_bytes };
    let chain_key = SecretKey { bytes: chain_bytes };

    insert_handle(HandlePayload::Ratchet(RatchetState {
        root_key,
        chain_key,
        step_index: 0,
        ephemeral_private: None,
        skip_keys: HashMap::new(),
    }))
}

/// Ratchet step: advance chain key, return message key handle.
///
/// NOTE: We must not call `insert_handle` inside `with_handle_mut` because
/// both acquire the global REGISTRY Mutex, causing a deadlock (std Mutex is
/// not reentrant). Instead we extract the derived bytes while holding the
/// lock, release it, then insert the new handle separately.
pub fn handle_ratchet_step(
    ratchet_handle: HandleId,
    step_info: &[u8],
    msg_info: &[u8],
) -> Result<HandleId, HandleError> {
    // Phase 1: mutate the ratchet state and extract the message key bytes.
    let msg_bytes = with_handle_mut(ratchet_handle, |payload| {
        let ratchet = match payload {
            HandlePayload::Ratchet(r) => r,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        // Derive message key from current chain key
        let salt = ratchet.step_index.to_be_bytes();
        let hkdf_msg = Hkdf::<Sha256>::new(Some(&salt), ratchet.chain_key.as_bytes());
        let mut msg_bytes = [0u8; 32];
        hkdf_msg
            .expand(msg_info, &mut msg_bytes)
            .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

        // Advance chain key
        let hkdf_step = Hkdf::<Sha256>::new(Some(&salt), ratchet.chain_key.as_bytes());
        let mut new_chain = [0u8; 32];
        hkdf_step
            .expand(step_info, &mut new_chain)
            .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

        ratchet.chain_key.bytes.zeroize();
        ratchet.chain_key = SecretKey { bytes: new_chain };
        ratchet.step_index += 1;

        Ok(msg_bytes)
    })?;

    // Phase 2: insert the message key handle (lock is no longer held).
    let msg_key = SecretKey { bytes: msg_bytes };
    insert_handle(HandlePayload::SymmetricKey(msg_key))
}

// ─── Public API: Mixed HKDF operations ──────────────────────────────────────

/// HKDF where IKM = (handle_key_bytes || extra_ikm), salt=salt, info=info.
/// Used for beacon mixing: HKDF(message_key || beacon_secret, salt, info).
/// All key material stays in Rust. Returns new handle.
pub fn handle_mix_hkdf(
    ikm_handle: HandleId,
    extra_ikm: &[u8],
    salt: &[u8],
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let mut ikm_bytes = with_handle(ikm_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::Session(s) => Ok(s.enc_key.as_bytes().to_vec()),
        HandlePayload::Ratchet(r) => Ok(r.chain_key.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    // Concatenate handle key bytes with extra IKM
    ikm_bytes.extend_from_slice(extra_ikm);

    let salt_opt: Option<&[u8]> = if salt.is_empty() { None } else { Some(salt) };
    let hkdf = Hkdf::<Sha256>::new(salt_opt, &ikm_bytes);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    // Zeroize the concatenated IKM
    ikm_bytes.zeroize();

    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// HKDF where the salt is a handle's key bytes and IKM is raw bytes.
/// Used for asymmetric root rekey: HKDF(IKM=shared_secret, salt=root_key, info=...).
/// Root key stays in Rust. Returns new handle.
pub fn handle_hkdf_with_handle_salt(
    ikm: &[u8],
    salt_handle: HandleId,
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let salt_bytes = with_handle(salt_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let hkdf = Hkdf::<Sha256>::new(Some(&salt_bytes), ikm);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// HKDF-Expand only (no Extract step). Treats handle's key as PRK directly.
/// Used for chain key derivation where chain_key is already a PRK.
pub fn handle_hkdf_expand(
    prk_handle: HandleId,
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let prk_bytes = with_handle(prk_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let prk = hkdf::Hkdf::<Sha256>::from_prk(&prk_bytes)
        .map_err(|e| HandleError::HkdfFailed(format!("Invalid PRK: {:?}", e)))?;
    let mut okm = vec![0u8; output_len];
    prk.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// Full HKDF where both IKM and salt come from handles.
/// Used for double ratchet root key derivation: HKDF(IKM=dh_output, salt=root_key).
pub fn handle_hkdf_two_handles(
    ikm_handle: HandleId,
    salt_handle: HandleId,
    info: &[u8],
    output_len: usize,
) -> Result<HandleId, HandleError> {
    let ikm_bytes = with_handle(ikm_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let salt_bytes = with_handle(salt_handle, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    let hkdf = Hkdf::<Sha256>::new(Some(&salt_bytes), &ikm_bytes);
    let mut okm = vec![0u8; output_len];
    hkdf.expand(info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let mut key_bytes = [0u8; 32];
    let copy_len = std::cmp::min(okm.len(), 32);
    key_bytes[..copy_len].copy_from_slice(&okm[..copy_len]);
    okm.zeroize();

    let key = SecretKey { bytes: key_bytes };
    insert_handle(HandlePayload::SymmetricKey(key))
}

// ─── Public API: Handle lifecycle ───────────────────────────────────────────

/// Drop (zeroize + free) a handle. Returns Ok(()) if it existed.
pub fn handle_drop(id: HandleId) -> Result<(), HandleError> {
    remove_handle(id)?;
    // HandlePayload drop impl zeroizes all secret material
    Ok(())
}

/// Check if a handle exists (for testing).
pub fn handle_exists(id: HandleId) -> bool {
    let reg = REGISTRY.lock().unwrap();
    reg.contains_key(&id)
}

/// Get current handle count (for testing / bounds checking).
pub fn handle_count() -> usize {
    let reg = REGISTRY.lock().unwrap();
    reg.len()
}

/// Import raw key bytes into a handle. Used ONLY at the Rust FFI boundary
/// for password-derived material. The raw bytes are consumed and stored
/// inside Rust; the Python caller's copy should be zeroized immediately.
pub fn handle_import_key(key_bytes: &[u8]) -> Result<HandleId, HandleError> {
    let key = SecretKey::new(key_bytes)?;
    insert_handle(HandlePayload::SymmetricKey(key))
}

/// DANGEROUS — use ONLY for encrypted-at-rest serialization or wire-protocol
/// fields (AAD, HKDF salt). The handle is NOT consumed (still valid).
/// Caller MUST zeroize the returned bytes immediately after use.
pub fn handle_export_key(id: HandleId) -> Result<Vec<u8>, HandleError> {
    with_handle(id, |payload| match payload {
        HandlePayload::SymmetricKey(k) => Ok(k.as_bytes().to_vec()),
        HandlePayload::X25519Key(k) => Ok(k.bytes.to_vec()),
        HandlePayload::HmacKey(h) => Ok(h.key.as_bytes().to_vec()),
        _ => Err(HandleError::HandleTypeMismatch),
    })
}

// ─── Public API: Stream chunk operations ────────────────────────────────────
// These enable chunk-by-chunk streaming encryption without leaking keys to Python.

/// AES-CTR crypt a chunk using stream handle's enc_key, nonce, and auto-tracked offset.
/// Key never leaves Rust. Only ciphertext/plaintext crosses FFI.
pub fn handle_stream_ctr_crypt(
    stream_handle: HandleId,
    data: &[u8],
) -> Result<Vec<u8>, HandleError> {
    with_handle_mut(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        let result = crypto_core::pure_crypto::aes_ctr_crypt(
            stream.enc_key.as_bytes(),
            &stream.nonce,
            data,
            stream.byte_offset,
        )
        .map_err(|_| HandleError::EncryptionFailed)?;

        stream.byte_offset += data.len() as u64;
        Ok(result)
    })
}

/// Compute HMAC-SHA256 using stream handle's internal MAC key.
/// MAC key never leaves Rust.
pub fn handle_stream_hmac(stream_handle: HandleId, message: &[u8]) -> Result<Vec<u8>, HandleError> {
    with_handle(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        let mut mac = <HmacSha256 as HmacMac>::new_from_slice(stream.mac_key.as_bytes())
            .map_err(|_| HandleError::EncryptionFailed)?;
        mac.update(message);
        Ok(mac.finalize().into_bytes().to_vec())
    })
}

/// Verify HMAC-SHA256 using stream handle's MAC key (constant-time).
pub fn handle_stream_hmac_verify(
    stream_handle: HandleId,
    message: &[u8],
    expected_tag: &[u8],
) -> Result<bool, HandleError> {
    let computed = handle_stream_hmac(stream_handle, message)?;
    if computed.len() != expected_tag.len() {
        return Ok(false);
    }
    Ok(computed.as_slice().ct_eq(expected_tag).into())
}

/// Get nonce from stream handle (non-secret metadata).
pub fn handle_stream_nonce(stream_handle: HandleId) -> Result<[u8; 16], HandleError> {
    with_handle(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };
        Ok(stream.nonce)
    })
}

/// Reset stream byte offset to 0 (for creating matching decrypt stream).
pub fn handle_stream_reset_offset(stream_handle: HandleId) -> Result<(), HandleError> {
    with_handle_mut(stream_handle, |payload| {
        let stream = match payload {
            HandlePayload::Stream(s) => s,
            _ => return Err(HandleError::HandleTypeMismatch),
        };
        stream.byte_offset = 0;
        Ok(())
    })
}

/// Generic AES-CTR crypt using any symmetric key handle + explicit nonce and offset.
/// Used by ratchet header encryption and other non-streaming AES-CTR paths.
pub fn handle_aes_ctr_crypt(
    key_handle: HandleId,
    nonce: &[u8],
    data: &[u8],
    byte_offset: u64,
) -> Result<Vec<u8>, HandleError> {
    if nonce.len() != 16 {
        return Err(HandleError::InvalidNonceLength {
            expected: 16,
            got: nonce.len(),
        });
    }

    with_handle(key_handle, |payload| {
        let key_bytes = match payload {
            HandlePayload::SymmetricKey(k) => k.as_bytes(),
            HandlePayload::Session(s) => s.enc_key.as_bytes(),
            HandlePayload::Ratchet(r) => r.chain_key.as_bytes(),
            _ => return Err(HandleError::HandleTypeMismatch),
        };

        crypto_core::pure_crypto::aes_ctr_crypt(key_bytes, nonce, data, byte_offset)
            .map_err(|_| HandleError::EncryptionFailed)
    })
}

// ─── Public API: PQXDH Hybrid Key Exchange (handle-only) ────────────────────

/// PQXDH-style hybrid encapsulation: X25519 + HMAC-Extract + HKDF-Expand.
///
/// Performs the full PQXDH key agreement inside Rust with no secret bytes
/// returned to the caller.  Returns (shared_secret_handle, ephemeral_pub).
///
/// Steps performed:
///   1. Generate ephemeral X25519 keypair
///   2. ECDH(ephemeral_private, receiver_classical_pub) → classical_shared
///   3. combined_ikm = classical_shared [|| pq_shared_secret]
///   4. PRK = HMAC-SHA256(extract_salt, combined_ikm)
///   5. transcript_hash = SHA-256(transcript_domain || eph_pub || receiver_pub [|| pq_pub] [|| pq_ct])
///   6. info = info_prefix || transcript_hash
///   7. shared_secret = HKDF-Expand(PRK, info, 32)
///   8. Store shared_secret as handle; zeroize all intermediates
///
/// All intermediate secrets (classical_shared, combined_ikm, PRK) are
/// zeroized before returning.  Only the ephemeral public key (non-secret)
/// crosses back to Python.
#[allow(clippy::too_many_arguments)]
pub fn handle_pqxdh_encapsulate(
    receiver_classical_pub: &[u8],
    pq_shared_secret: Option<&[u8]>,
    extract_salt: &[u8],
    info_prefix: &[u8],
    transcript_domain: &[u8],
    receiver_pq_pub: Option<&[u8]>,
    pq_ciphertext: Option<&[u8]>,
) -> Result<(HandleId, [u8; 32]), HandleError> {
    if receiver_classical_pub.len() != 32 {
        return Err(HandleError::InvalidPublicKeyLength);
    }

    // 1. Generate ephemeral X25519 keypair
    let (eph_private, eph_public) = X25519Private::generate();

    // 2. ECDH
    let mut pub_bytes = [0u8; 32];
    pub_bytes.copy_from_slice(receiver_classical_pub);
    let mut classical_shared = eph_private.exchange(&pub_bytes);

    // 3. Combine IKM
    let mut combined_ikm = classical_shared.to_vec();
    if let Some(pq_ss) = pq_shared_secret {
        combined_ikm.extend_from_slice(pq_ss);
    }

    // 4. HMAC-Extract: PRK = HMAC-SHA256(extract_salt, combined_ikm)
    let mut mac = <HmacSha256 as HmacMac>::new_from_slice(extract_salt)
        .map_err(|_| HandleError::HkdfFailed("HMAC init failed".into()))?;
    mac.update(&combined_ikm);
    let prk = mac.finalize().into_bytes();
    combined_ikm.zeroize();
    classical_shared.zeroize();

    // 5. Transcript hash
    let mut transcript_data = transcript_domain.to_vec();
    transcript_data.extend_from_slice(&eph_public);
    transcript_data.extend_from_slice(receiver_classical_pub);
    if let Some(rpq) = receiver_pq_pub {
        transcript_data.extend_from_slice(rpq);
    }
    if let Some(pq_ct) = pq_ciphertext {
        transcript_data.extend_from_slice(pq_ct);
    }
    use sha2::{Digest, Sha256 as Sha256Hasher};
    let transcript_hash = Sha256Hasher::digest(&transcript_data);

    // 6. Info = prefix || transcript_hash
    let mut info = info_prefix.to_vec();
    info.extend_from_slice(&transcript_hash);

    // 7. HKDF-Expand(PRK, info, 32)
    let hkdf = hkdf::Hkdf::<Sha256>::from_prk(&prk)
        .map_err(|e| HandleError::HkdfFailed(format!("PRK: {:?}", e)))?;
    let mut okm = [0u8; 32];
    hkdf.expand(&info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    // 8. Store as handle
    let key = SecretKey::new(&okm)?;
    okm.zeroize();
    let handle = insert_handle(HandlePayload::SymmetricKey(key))?;

    Ok((handle, eph_public))
}

/// PQXDH-style hybrid decapsulation (receiver side).
///
/// Same derivation as encapsulate but uses the receiver's private key handle
/// for the ECDH step.  No secret bytes cross the FFI boundary.
#[allow(clippy::too_many_arguments)]
pub fn handle_pqxdh_decapsulate(
    ephemeral_classical_pub: &[u8],
    receiver_private_handle: HandleId,
    pq_shared_secret: Option<&[u8]>,
    receiver_classical_pub: &[u8],
    extract_salt: &[u8],
    info_prefix: &[u8],
    transcript_domain: &[u8],
    receiver_pq_pub: Option<&[u8]>,
    pq_ciphertext: Option<&[u8]>,
) -> Result<HandleId, HandleError> {
    if ephemeral_classical_pub.len() != 32 {
        return Err(HandleError::InvalidPublicKeyLength);
    }
    if receiver_classical_pub.len() != 32 {
        return Err(HandleError::InvalidPublicKeyLength);
    }

    // 1. ECDH using receiver private handle
    let mut eph_pub = [0u8; 32];
    eph_pub.copy_from_slice(ephemeral_classical_pub);
    let mut classical_shared = with_handle(receiver_private_handle, |payload| match payload {
        HandlePayload::X25519Key(k) => Ok(k.exchange(&eph_pub)),
        _ => Err(HandleError::HandleTypeMismatch),
    })?;

    // 2. Combine IKM
    let mut combined_ikm = classical_shared.to_vec();
    if let Some(pq_ss) = pq_shared_secret {
        combined_ikm.extend_from_slice(pq_ss);
    }

    // 3. HMAC-Extract
    let mut mac = <HmacSha256 as HmacMac>::new_from_slice(extract_salt)
        .map_err(|_| HandleError::HkdfFailed("HMAC init failed".into()))?;
    mac.update(&combined_ikm);
    let prk = mac.finalize().into_bytes();
    combined_ikm.zeroize();
    classical_shared.zeroize();

    // 4. Transcript hash
    let mut transcript_data = transcript_domain.to_vec();
    transcript_data.extend_from_slice(ephemeral_classical_pub);
    transcript_data.extend_from_slice(receiver_classical_pub);
    if let Some(rpq) = receiver_pq_pub {
        transcript_data.extend_from_slice(rpq);
    }
    if let Some(pq_ct) = pq_ciphertext {
        transcript_data.extend_from_slice(pq_ct);
    }
    use sha2::{Digest, Sha256 as Sha256Hasher};
    let transcript_hash = Sha256Hasher::digest(&transcript_data);

    // 5. Info
    let mut info = info_prefix.to_vec();
    info.extend_from_slice(&transcript_hash);

    // 6. HKDF-Expand
    let hkdf = hkdf::Hkdf::<Sha256>::from_prk(&prk)
        .map_err(|e| HandleError::HkdfFailed(format!("PRK: {:?}", e)))?;
    let mut okm = [0u8; 32];
    hkdf.expand(&info, &mut okm)
        .map_err(|e| HandleError::HkdfFailed(format!("{:?}", e)))?;

    let key = SecretKey::new(&okm)?;
    okm.zeroize();
    insert_handle(HandlePayload::SymmetricKey(key))
}

