        let ct = handle_aes_gcm_encrypt(h, &nonce, b"test_keyfile", None).unwrap();
        let pt = handle_aes_gcm_decrypt(h, &nonce, &ct, None).unwrap();
        assert_eq!(pt, b"test_keyfile");

