        let result = handle_derive_key_argon2id_with_keyfile(
            b"password",
            b"keyfile",
            b"domain",
            &[0u8; 8], // wrong salt length
            1024,
            1,
            1,
        );
        assert!(result.is_err());
    }

    #[test]
