    fn test_argon2id_different_salts() {
        let password = b"password";
        let key1 = derive_key_argon2id(password, &[0x11u8; 16], 1024, 1, 1, 32).unwrap();
        let key2 = derive_key_argon2id(password, &[0x22u8; 16], 1024, 1, 1, 32).unwrap();
        assert_ne!(key1, key2);
    }

