        // Correct length
        assert_eq!(walk.len(), 100);

        // Is a permutation (all elements present)
        let mut sorted = walk.clone();
        sorted.sort();
        let expected: Vec<u32> = (0..100).collect();
        assert_eq!(sorted, expected);
    }

